(window.TNQ=window.TNQ||[]).push({"terms":{"카테고리분석법":{"d":"가구 특성별로 나눈 집단마다 통행 원단위를 정해 통행발생량을 구하는 방법입니다.","r":["원단위분석법","회귀분석법"]},"원단위분석법":{"d":"단위당 통행 발생량(원단위)에 활동량을 곱해 통행발생량을 구하는 방법입니다.","r":["카테고리분석법"]},"회귀분석법":{"d":"종속변수와 독립변수의 관계를 식으로 세워 통행발생량 등을 추정하는 방법입니다.","r":["카테고리분석법"]},"설계속도":{"d":"도로의 기하구조를 정하는 기준이 되는 속도입니다.","r":["편경사"]},"편경사":{"d":"곡선부에서 원심력에 대응하려고 차도를 안쪽으로 기울여 주는 횡단경사입니다.","r":["설계속도"]},"완화곡선":{"d":"직선과 원곡선 사이에서 곡률을 서서히 변화시키는 곡선입니다.","r":["클로소이드"]},"클로소이드":{"d":"곡률이 곡선 길이에 비례해 변하는 대표적인 완화곡선입니다.","r":["완화곡선"]},"공간평균속도":{"d":"일정 구간 안에 있는 차량의 속도를 평균한 값입니다.","r":[]},"사용자균형":{"d":"어떤 이용자도 경로를 바꿔 통행시간을 줄일 수 없는 상태의 교통량 배정입니다.","r":["Braess 역설"]},"Braess 역설":{"d":"새 링크를 지었는데도 오히려 모든 이용자의 통행시간이 늘어나는 현상입니다.","r":["사용자균형"]},"임계밀도":{"d":"교통량이 최대가 될 때의 교통류 밀도입니다.","r":["차두시간"]},"차두시간":{"d":"앞차와 뒤차가 같은 지점을 통과하는 시각의 차이입니다.","r":["임계밀도"]},"스키드마크":{"d":"급제동으로 바퀴가 미끄러지며 노면에 남긴 타이어 자국입니다.","r":["마찰계수"]},"마찰계수":{"d":"타이어와 노면 사이의 미끄러짐에 대한 저항 정도를 나타내는 값입니다.","r":["스키드마크"]},"도류화":{"d":"교통섬과 노면표시로 차량이 가야 할 경로를 정해 주고 상충을 줄이는 것입니다.","r":[]},"충격파":{"d":"교통류 밀도나 속도가 급변하는 경계가 도로를 따라 퍼져 나가는 현상입니다.","r":[]},"포아송분포":{"d":"일정 시간에 도착하는 차량 대수처럼 드문 사건의 횟수를 설명하는 확률분포입니다.","r":["음지수분포"]},"음지수분포":{"d":"차량이 도착하는 간격처럼 사건 사이의 시간을 설명하는 확률분포입니다.","r":["포아송분포"]},"로짓모형":{"d":"여러 대안의 효용으로 선택 확률을 구하는 개별행태 모형입니다.","r":["프로빗모형"]},"프로빗모형":{"d":"효용의 오차가 정규분포를 따른다고 보고 선택 확률을 구하는 개별행태 모형입니다.","r":["로짓모형"]},"중력모형":{"d":"두 존 사이의 통행량이 크기에 비례하고 거리에 반비례한다고 보는 통행분포 모형입니다.","r":["성장률법"]},"성장률법":{"d":"현재 통행량에 존별 성장률을 곱해 장래 통행분포를 구하는 방법입니다.","r":["중력모형"]},"중앙분리대":{"d":"서로 반대 방향으로 가는 교통류를 갈라 정면충돌 등을 막는 도로 시설입니다.","r":["길어깨"]},"길어깨":{"d":"차도 바깥쪽에 붙어 고장차 대피와 도로 보호를 맡는 부분입니다.","r":["비상주차대"]},"비상주차대":{"d":"길어깨가 좁은 구간에서 고장차가 대피할 수 있게 마련한 정차 공간입니다.","r":["길어깨"]},"전원도시":{"d":"하워드가 제안한 도시와 농촌의 장점을 합친 자족적인 소규모 도시입니다.","r":["위성도시"]},"위성도시":{"d":"중심도시 가까이에 있으나 독립된 기능을 갖춘 도시입니다.","r":["전원도시"]},"방사환상형":{"d":"중심에서 사방으로 뻗은 방사도로를 환상도로가 연결하는 도로망 형태입니다.","r":[]},"쿨데삭":{"d":"한쪽 끝이 막혀 통과교통이 들어오지 못하는 막다른 도로입니다.","r":[]},"지구단위계획":{"d":"지구 단위로 건축물 배치와 기반시설 등을 계획해 토지이용을 합리화하는 계획입니다.","r":[]},"공동구":{"d":"전기, 통신, 상하수도 등 여러 지하매설물을 함께 수용하는 지하 시설물입니다.","r":[]},"건폐율":{"d":"대지면적에 대한 건축면적의 비율입니다.","r":["용적률"]},"용적률":{"d":"대지면적에 대한 건축물 연면적의 비율입니다.","r":["건폐율"]},"치사율":{"d":"사고 100건당 사망자 수를 나타내는 비율입니다.","r":[]},"K계수":{"d":"연평균일교통량 대비 설계시간교통량의 비율입니다.","r":["AADT"]},"AADT":{"d":"1년 동안의 총교통량을 365로 나눈 연평균일교통량입니다.","r":["K계수"]},"PIEV":{"d":"운전자가 지각, 식별, 판단, 반응의 순서로 대응하는 과정입니다.","r":[]},"TSM":{"d":"기존 시설을 적은 투자로 효율적으로 이용해 교통 문제를 줄이려는 단기 관리 기법입니다.","r":[]},"BRT":{"d":"버스전용차로와 운행관리시스템 등으로 철도에 가까운 서비스를 내는 버스 체계입니다.","r":[]},"AHP":{"d":"계층적으로 요소를 나누고 쌍대비교로 상대적 중요도를 정해 의사결정을 돕는 기법입니다.","r":[]},"로지스틱곡선법":{"d":"인구성장이 S자형을 그린다고 보고 장래 인구를 예측하는 방법입니다.","r":[]},"옵션존":{"d":"황색신호 때 정지할지 통과할지 판단하기 어려운 구간입니다.","r":[]}},"notes":{"1.3배는 고속도로 확대 비율 기준이 아니다":"고속도로 확대 비율의 기준으로 1.3배를 쓰지 않습니다.","1.5m나 2.0m, 3.0m는 기준이 아니다":"기준값에 1.5m, 2.0m, 3.0m는 해당하지 않습니다.","10~20%(또는 8~20%)가 기준이다":"도로율 기준은 공업지역이 10~20%(또는 8~20%)입니다.","10부제 운행과 공영주차장 요금인상은 집행이 쉬우며 버스 이용은 정치적 수용성이 낮지 않다":"버스 이용은 정치적 수용성이 낮지 않으며 10부제 운행과 공영주차장 요금인상은 집행이 쉽습니다.","14초·13초·15초로 계산되지는 않는다":"이 계산 결과가 14초, 13초, 15초로 나오지는 않습니다.","15분보다 짧으면 PHF가 작아져 과도설계가 될 수 있다":"PHF는 분석시간단위를 15분보다 짧게 잡으면 작아져서 과도설계가 될 수 있습니다.","1920년대 시카고 사례로 도시 토지이용의 생태학적 과정을 제시했다":"도시 토지이용의 생태학적 과정을 1920년대 시카고 사례로 제시했습니다.","1958년 헤이그 세미나는 철거·수복·보전재개발로 분류했다":"1958년 헤이그 세미나는 재개발을 철거, 수복, 보전재개발 세 가지로 분류했습니다.","1분간 도착 0대 확률은 약 13.5%다":"1분 동안 도착하는 차가 0대일 확률은 약 13.5%로 계산됩니다.","1분당 보행자 200~240인이면 횡단보도교 폭은 4m 이상이다":"보행자가 1분당 200~240인이면 횡단보도교 폭을 4m 이상으로 합니다.","1분당 보행자 80인 미만이면 최소폭 1.5m, 계단 경사도는 50% 이하다":"계단 경사도는 50% 이하이고, 1분당 보행자가 80인 미만이면 최소폭을 1.5m로 합니다.","1인 회답자로부터 복수 데이터를 얻을 수 있다":"복수 데이터를 1인 회답자로부터 얻을 수 있는 것이 SP데이터입니다.","25~35%가 도로율 기준이다":"도로율 기준은 상업지역이 25~35%입니다.","2천m 내외가 아니라 1,000m 내외다":"주간선도로끼리의 간격은 2천m 내외가 아니라 1,000m 내외입니다.","3.0~6.0%가 횡단경사 기준이다":"비포장도로의 횡단경사 기준은 3.0~6.0%입니다.","30일 이내 사망하면 사망사고로 분류한다":"사고가 나고 30일 안에 사망하면 그 사고를 사망사고로 봅니다.","3대 가치에 포함되지 않는다":"보전적 가치는 3대 가치에 포함되지 않습니다.","3지 교차로 교차상충은 3개, 4지 교차로는 16개다":"교차상충은 4지 교차로가 16개, 3지 교차로가 3개입니다.","4단계의 마지막 단계이며 개별행태모형 유형과는 다르다":"통행배정은 4단계 추정법의 마지막 단계이며 개별행태모형 유형과는 다릅니다.","4차로 이상 고속도로는 반드시 중앙분리대를 설치하며 분리대와 측대로 구성된다":"분리대와 측대로 이뤄진 중앙분리대는 4차로 이상 고속도로에 반드시 설치합니다.","50km/h 이상 기준이 아니다":"도시지역 국지도로는 50km/h 이상 기준이 아닙니다.","5m 이하 토지분할, 토석 채취, 토지형상 변경이 개발행위허가 대상이다":"토석 채취와 토지형상 변경, 5m 이하 토지분할은 개발행위허가를 받아야 합니다.","60km/h에서 최소시거가 120m인 것은 아니다(75m가 기준)":"75m가 기준이며 60km/h에서 최소시거 120m는 틀립니다.","90도 각도주차는 1대당 소요면적이 작다":"1대당 소요면적이 작은 것은 90도 각도주차입니다.","AADT, 첨두시간 비율, 중방향 비율이 첨두시간 설계교통량 결정요소다":"첨두시간 설계교통량은 AADT, 첨두시간 비율, 중방향 비율로 결정합니다.","AADT가 늘면 K30은 일반적으로 감소한다":"AADT가 늘어나면 K30은 일반적으로 줄어듭니다.","AADT가 큰 도로는 K계수가 비교적 낮고 개발밀도가 증가하면 K계수는 감소한다":"개발밀도가 증가하면 K계수가 감소하고 AADT가 큰 도로는 K계수가 비교적 낮습니다.","AADT 산정 기본교통량을 구하려 필요한 모든 구간에서 한다":"AADT를 산정하는 기본교통량을 구하려고 필요한 모든 구간에서 전역조사를 합니다.","B/C비는 이해하기 쉽고 사업규모를 고려할 수 있다":"사업규모를 고려할 수 있고 이해하기 쉬운 것이 B/C비의 장점입니다.","Baumol-Quandt, McLynn, Kraft-SARC 모형이 직접수요추정모형이다":"직접수요추정모형에는 Baumol-Quandt, McLynn, Kraft-SARC 모형이 있습니다.","Greenberg 지수모형은 저밀도에서 관측치와 안 맞고 Underwood는 고속에서 잘 안 맞는다":"Greenberg 지수모형은 저밀도에서, Underwood는 고속에서 관측치와 잘 맞지 않습니다.","K30이 높을수록 교통량 변화가 심하며 관광도로에서 가장 높다":"관광도로에서 가장 높은 K30은 높을수록 교통량 변화가 심합니다.","K계수가 클수록 교통량 변화가 적은 것은 아니다":"K계수가 클수록 교통량 변화가 적다는 설명은 틀립니다.","LQ<1이면 수입의존형, LQ>1이면 수출산업, LQ=0이면 그 산업이 존재하지 않는다":"LQ가 1보다 작으면 수입의존형, 크면 수출산업이고 0이면 그 산업이 존재하지 않습니다.","LQ=1이 쇠퇴를 뜻하는 것은 아니다":"쇠퇴를 뜻하는 값은 LQ가 1일 때가 아닙니다.","NPV는 교통사업 경제성분석에 보편적으로 쓰이며 할인율로 현재가치화한다":"교통사업 경제성분석에 보편적으로 쓰이는 NPV는 할인율로 현재가치화합니다.","PHF는 보통 1보다 작은 값을 가지며 도로용량 분석에 쓰인다":"도로용량 분석에 쓰이는 PHF는 대개 1보다 작은 값으로 나옵니다.","Park and Ride, 도심통행료, 출퇴근시간 조정은 교통수요 관리기법이고 주차장 신설은 아니다":"주차장 신설은 교통수요 관리기법이 아니며 Park and Ride, 도심통행료, 출퇴근시간 조정이 관리기법입니다.","R. Unwin, R. Whitten, G. R. Taylor는 위성도시론을 주장한 학자다":"위성도시론을 주장한 학자는 R. Unwin, R. Whitten, G. R. Taylor입니다.","Skid mark는 스커프마크가 아니다":"스커프마크에 Skid mark는 해당하지 않습니다.","TSM은 소규모 투자사업이며 교통요소 간 유기적 연관성을 도모한다":"교통요소 간 유기적 연관성을 도모하며 TSM은 소규모 투자사업입니다.","Yaw mark, Acceleration scuff, Flat tire mark는 스커프마크에 해당한다":"스커프마크로 분류되는 것은 Yaw mark, Acceleration scuff, Flat tire mark입니다.","Y형, T형, 회전교차로가 평면교차로 종류이고 다이아몬드형·클로버형은 입체교차로다":"평면교차로 종류는 Y형, T형, 회전교차로이고 다이아몬드형·클로버형은 입체교차로입니다.","km당 평균사고율은 고속도로가 지방부도로보다 낮지 않다":"고속도로가 지방부도로보다 km당 평균사고율이 낮다고 볼 수 없습니다.","가각주차제한, 가로조명개선, 시야장애물 제거는 비신호교차로 직각충돌 예방책이다":"비신호교차로 직각충돌은 가각주차제한, 가로조명개선, 시야장애물 제거로 예방합니다.","가격이 일정하다고 가정해 대체효과를 반영하지 못한다":"지역간 투입산출법은 가격이 일정하다고 가정해 대체효과를 반영하지 못합니다.","가능한 넓은 지역을 포함시키는 것이 원칙은 아니다":"가능한 넓은 지역을 포함시키는 것은 폐쇄선의 원칙이 아닙니다.","가로변 면담조사, 운전자 우편설문조사도 포함된다":"조사 방법에는 가로변 면담조사도, 운전자 우편설문조사도 들어갑니다.","가상상황에 대한 대안도 평가할 수 있다":"가상상황에 대한 대안도 평가할 수 있는 점이 SP데이터의 특징입니다.","가속에 영향을 미치는 요소가 아니다":"가속에 영향을 미치는 요소 가운데 차체 크기는 빠집니다.","가속해 반대편 차로 진입 직전까지 주행거리, 진입 후 앞지르기까지 거리를 고려한다":"앞지르기 전에는 반대편 차로 진입 직전까지 가속해 주행한 거리를, 진입한 뒤에는 앞지르기까지의 거리를 따집니다.","가시거리 100m 이내 폭우·폭설·안개, 노면 결빙, 눈 20mm 이상은 50% 감속 대상이다":"폭우·폭설·안개로 가시거리 100m 이내이거나 노면이 결빙되었거나 눈이 20mm 이상이면 50% 감속합니다.","가시구간 최소길이는 철도차량 최고속도에 따라 110~350m다":"철도차량 최고속도에 따라 가시구간 최소길이는 110~350m로 달라집니다.","가파른 비탈길 오르막은 서행 의무 장소가 아니다(내리막이 대상)":"서행 의무 장소는 가파른 비탈길 내리막이며 오르막은 아닙니다.","각도주차보다 주차용량을 늘리지는 못한다":"평행주차는 각도주차보다 주차용량을 늘리지는 못합니다.","간격 최소 1km·최대 20km 이하가 기준은 아니다(비용편익비 극대화가 기준)":"비용편익비를 극대화하는 것이 기준이고, 최소 1km·최대 20km 이하라는 간격 기준은 틀립니다.","간선도로·교차로 교통량 현황과 변화추이도 조사한다":"변화추이와 간선도로·교차로 교통량 현황도 조사 대상입니다.","간선도로·국지도로·집산도로는 기능상 분류이고 이면도로는 아니다":"이면도로는 기능상 분류가 아니며 간선도로, 국지도로, 집산도로가 기능상 분류입니다.","간선도로는 국가교통 체계가 아니다":"국가교통 체계에 간선도로는 속하지 않습니다.","간선도로·보조간선도로의 주기능은 접근성이 아니라 이동성이다":"이동성이 간선도로와 보조간선도로의 주기능이며 접근성은 주기능이 아닙니다.","간선·보조간선 기능 수행 도로는 지방도 정의가 아니다":"지방도 정의에 간선·보조간선 기능 수행 도로는 들지 않습니다.","간섭기회모형은 목적지 선택기회를, 엔트로피극대화모형은 통행유출입을 설명한다":"목적지 선택기회는 간섭기회모형이, 통행유출입은 엔트로피극대화모형이 설명합니다.","감속길이·대기차로길이·진입테이퍼길이가 보조차로 길이 요소이고 회전반경길이는 아니다":"회전반경길이는 보조차로 길이 요소가 아니며 감속길이, 대기차로길이, 진입테이퍼길이가 요소입니다.","강력한 중심부를 형성하고 중심부 접근성이 양호하며 다양한 도시구조를 만든다":"중심부 접근성이 양호하고 강력한 중심부를 형성하여 다양한 도시구조를 만들 수 있습니다.","같은 방향에서 시험차를 추월·추월당하는 차량 수, 반대방향에서 만나는 차량 수를 조사한다":"시험차를 같은 방향에서 추월하거나 추월당한 차량 수와 반대방향에서 만난 차량 수를 조사합니다.","개발계획 평가지표는 이용객수, 연계교통망 수준, 환승편의시설 수준이고 지자체 추진의지는 아니다":"지자체 추진의지는 평가지표가 아니며 이용객수, 연계교통망 수준, 환승편의시설 수준이 평가지표입니다.","개발제한권역·개발유보권역은 권역 구분에 포함되지 않는다":"권역 구분에 개발제한권역·개발유보권역은 포함되지 않습니다.","개별행태 모형의 분석방법이 아니다":"개별행태 분석방법에 중력모형은 들지 않습니다.","개선지점과 대조지점의 분석기간은 동일해야 한다":"개선지점과 대조지점의 분석기간은 서로 같아야 합니다.","개인의 통행행태 자료를 활용하고 타존에 적용 가능하며 수요추정과정 통합이 가능하다":"개별행태 모형은 개인의 통행행태 자료를 활용하고 타존에 적용할 수 있으며 수요추정과정을 통합할 수 있습니다.","개인의 행태적 특성을 고려하지 않는다":"중력모형은 개인의 행태적 특성을 고려하지 않습니다.","거점개발방식 확산과 성장거점도시 육성은 제3차 계획 목표가 아니다(이전 계획)":"이전 계획의 목표이며 제3차 계획의 목표가 아닌 것이 거점개발방식 확산과 성장거점도시 육성입니다.","거주인구를 주택부지로 나눈 값이며 지구 전체 토지면적 기준이 아니다":"지구 전체 토지면적이 아니라 주택부지를 기준으로 거주인구를 나눈 것이 순밀도입니다.","건널목 양측 30m 이내는 직선으로 하고 종단구배 3% 이하로 한다":"종단구배 3% 이하, 양측 30m 이내 직선이 건널목의 기준입니다.","건물연면적 원단위법, 교통량 원단위법, 주차발생 원단위법이 원단위법 종류다":"원단위법 종류에는 건물연면적 원단위법, 교통량 원단위법, 주차발생 원단위법이 있습니다.","건설비가 비싸고 범죄 가능성이 크며 방향감각을 잃기 쉽다":"지하식 보행시설은 방향감각을 잃기 쉽고 건설비가 비싸며 범죄 가능성이 큽니다.","건조한 노면이 습윤한 노면보다 마찰계수가 크다":"마찰계수가 더 큰 쪽은 습윤한 노면이 아니라 건조한 노면입니다.","건축물 건축, 토석 채취, 1개월 이상 물건 적치가 개발행위에 해당한다":"개발행위에는 건축물 건축, 토석 채취, 1개월 이상 물건 적치가 해당합니다.","건폐율 90% 이하, 용적률 1500% 이하가 주차전용건축물 기준이다":"주차전용건축물은 건폐율 90% 이하, 용적률 1500% 이하여야 합니다.","검지기 설치·관리가 쉬운 것은 감응신호의 장점이 아니다":"검지기를 설치하고 관리하기 쉽다는 점은 감응신호의 장점이 아닙니다.","격자형, 방사형, 격자방사형은 간선·보조간선도로 가로망 형태다":"간선·보조간선도로 가로망 형태는 격자형, 방사형, 격자방사형입니다.","격자형 가로망을 도입했고 아고라가 두 개 있었다":"격자형 가로망을 도입한 밀레투스에는 아고라가 두 개 있었습니다.","격자형 도로망을 발전시켰고 도시민 주택은 폐쇄형 중정 배치였다":"격자형 도로망을 발전시킨 히포다무스 계획에서 도시민 주택은 폐쇄형 중정 배치였습니다.","견딜만한 최대 감속을 유지하고 차량이 관통·튀어오르지 않게 방향을 수정해야 한다":"방호책은 차량이 관통하거나 튀어오르지 않게 방향을 수정하고 견딜 만한 최대 감속을 유지해야 합니다.","경관지구는 경관 보호, 방재지구는 재해 예방 목적이다":"재해 예방이 방재지구의 목적이고 경관 보호가 경관지구의 목적입니다.","경사, 마찰계수, 편주흔(요마크) 곡선반경이 속도 추정 요소다":"속도 추정에는 경사와 마찰계수, 편주흔(요마크) 곡선반경이 요소로 쓰입니다.","경사로 종단구배는 직선부 17%, 곡선부 14%를 넘지 않는다":"직선부 17%, 곡선부 14%를 넘지 않는 것이 경사로 종단구배 한도입니다.","경험·회피도 PIEV 과정의 요소가 아니다":"경험과 회피도 PIEV 과정을 이루는 요소가 아닙니다.","계단높이·보행점유공간으로 측정하지 않는다":"계단은 계단높이와 보행점유공간으로 측정하지 않습니다.","계산이 쉽고 토지이용 특성을 반영하기 좋으나 교통체계 최적화에는 안 맞는다":"원단위법은 계산이 쉽고 토지이용 특성을 반영하기 좋지만 교통체계 최적화에는 맞지 않습니다.","계층적 구조설정, 상대적 중요도 설정, 논리적 일관성이 AHP 3대 원리다":"AHP 3대 원리는 계층적 구조설정, 상대적 중요도 설정, 논리적 일관성입니다.","계통추출법·집락추출법은 확률추출법이다":"확률추출법에는 계통추출법과 집락추출법이 속합니다.","계획가·분석가의 주관이 작용할 수 있고 총체적 자료로 평균적 특성만 산출된다":"총체적 자료로 평균적 특성만 산출되며 계획가와 분석가의 주관이 작용할 수 있습니다.","계획부터 운영까지 모든 단계에 적용 가능하며 미국이 최초는 아니다":"미국이 최초는 아니며 계획부터 운영까지 모든 단계에 적용할 수 있습니다.","고속국도와 다른 도로·철도 교차 시 평면교차시설로 하는 것이 원칙은 아니다(입체교차 원칙)":"입체교차가 원칙이므로 고속국도와 다른 도로·철도 교차 시 평면교차시설이 원칙은 아닙니다.","고속국도·일반국도·국가지원지방도의 건설관리계획을 수립하며 지방도는 아니다":"지방도는 대상이 아니며 고속국도, 일반국도, 국가지원지방도의 건설관리계획을 수립합니다.","고속도로(자동차전용도로 포함)에서 안전표지는 기본규격의 2배까지 확대할 수 있다":"안전표지는 기본규격의 2배까지 고속도로(자동차전용도로 포함)에서 확대할 수 있습니다.","고속도로, 철도, 항만이 국가교통 체계에 속한다":"국가교통 체계에는 고속도로, 철도, 항만이 속합니다.","고속도로·도시고속도로·주간선도로에 설치하며 이용횟수·승하차 인원을 고려한다":"이용횟수와 승하차 인원을 고려해 고속도로, 도시고속도로, 주간선도로에 설치합니다.","고속도로에서 고장 정차, 통행료 지불, 도로 유지보수 정차는 예외로 허용된다":"통행료를 내거나 도로 유지보수를 하거나 고장이 나서 서는 경우는 고속도로에서도 예외로 허용됩니다.","고속도로에서는 승차정원을 초과할 수 없다":"승차정원을 초과해 태울 수 없는 곳이 고속도로입니다.","고속도로 우측 길어깨 폭원 2.0m 미만이면 비상주차대 설치 대상이다":"우측 길어깨 폭원이 2.0m에 못 미치는 고속도로는 비상주차대 설치 대상이 됩니다.","고속도로 우측 길어깨 폭원 2.50m 미만이면 비상주차대를 설치해야 한다":"비상주차대는 고속도로 우측 길어깨 폭원이 2.50m 미만일 때 설치합니다.","고속도로·자동차전용도로·고가도로에는 설치할 수 없고 20대 이상이면 장애인구획을 설치한다":"장애인구획은 20대 이상이면 설치하고 고속도로, 자동차전용도로, 고가도로에는 설치하지 않습니다.","고속도로·자동차전용도로에 설치할 수 없고 종단경사 4% 초과도 금지된다":"노상주차장은 고속도로와 자동차전용도로에 설치할 수 없고 종단경사 4%를 넘는 곳도 금지됩니다.","고속도로·주간선도로는 세미트레일러, 보조간선도로는 대형자동차가 기준이다":"세미트레일러는 고속도로와 주간선도로, 대형자동차는 보조간선도로의 설계기준입니다.","고속도로 지방지역은 3.5m 이상, 일반도로 설계속도 80kph 이상 도시지역은 3.25m 이상이다":"차로 폭은 고속도로 지방지역이 3.5m 이상, 설계속도 80kph 이상 일반도로 도시지역이 3.25m 이상입니다.","고속도로·지방지역 일반도로 비상주차대 설치간격은 750m가 표준이다":"고속도로와 지방지역 일반도로의 비상주차대는 750m 간격이 표준입니다.","고속·저속 자동차 구성비, 오르막경사 완화와의 경제성 비교, 사고예방 효과를 검토한다":"사고예방 효과와 고속·저속 자동차 구성비, 오르막경사 완화와의 경제성 비교를 검토합니다.","고속 좌측차로에서 분합류해 위험하며 좌회전 교통이 주류인 곳에 쓴다":"좌회전 교통이 주류인 곳에 쓰는 좌직결 연결로는 고속 좌측차로에서 분합류해 위험합니다.","고용자수, 지역소득, 지역총생산이 정량적 예측변수다":"정량적 예측변수에는 고용자수, 지역소득, 지역총생산이 있습니다.","고정된 경로비용으로 최소비용경로 알고리즘을 적용한다":"정태적 모형은 고정된 경로비용에 최소비용경로 알고리즘을 적용합니다.","고정 지점에서 단위시간에 관측한 차의 평균속도다":"시간평균속도는 고정 지점에서 단위시간에 관측한 차량의 평균속도입니다.","곡선반경, 시거, 편경사는 설계속도와 직접 관계있다":"설계속도와 직접 관계가 있는 것은 곡선반경, 시거, 편경사입니다.","곡선부는 미끄러짐 사고가 쉽고 종단경사와 겹치면 위험이 커진다":"종단경사와 겹치면 위험이 커지고 곡선부는 미끄러짐 사고가 쉽습니다.","공간적 질의, 근린성 분석, 지리적 처리에 쓰인다":"점 자료를 분석할 때 공간적 질의, 근린성 분석, 지리적 처리를 합니다.","공간평균속도보다 크거나 같다":"시간평균속도는 공간평균속도보다 크거나 같습니다.","공공의 재정지원, 주민참여 활성화, 건축규제 예외성 인정이 실현 조건이며 개발계획 중심 수립은 아니다":"개발계획 중심 수립은 실현 조건이 아니며 공공의 재정지원, 주민참여 활성화, 건축규제 예외성 인정이 조건입니다.","공동구 내 통로는 높이 2.1m 이상, 너비 0.8m 이상이 기준이다":"공동구 안 통로는 너비 0.8m 이상, 높이 2.1m 이상이어야 합니다.","공영버스는 정치적 간섭을 받고 비용 면에서 민영보다 비효율적이다":"비용 면에서 민영보다 비효율적이고 정치적 간섭을 받는 것이 공영버스입니다.","공익적 관점에서 공원·녹지계획을 우선 고려한다":"공익적 관점을 우선해 공원·녹지계획을 고려합니다.","공학·규제·교육이 3E이고 환경(Environment)은 포함되지 않는다":"3E는 공학, 규제, 교육이며 환경(Environment)은 포함되지 않습니다.","공항, 무역항, 고속·광역·일반철도는 국가기간 교통시설이다":"국가기간 교통시설에는 공항, 무역항, 고속·광역·일반철도가 있습니다.","과거추세연장법, 주차 원단위법, 기종점조사법이 주차수요 추정법이고 외삽법은 아니다":"외삽법은 주차수요 추정법이 아니며 과거추세연장법, 주차 원단위법, 기종점조사법이 추정법입니다.","과거추세연장법 적용이 어렵거나 기간산업 판별이 힘들 때 쓴다":"비교유추법은 과거추세연장법을 적용하기 어렵거나 기간산업 판별이 힘들 때 씁니다.","과밀억제권역, 성장관리권역, 자연보전권역이 수도권 권역 구분이다":"수도권 권역은 과밀억제권역, 성장관리권역, 자연보전권역으로 구분합니다.","과속방지턱 설치, 곡선형 도로로 감속 유도, 접근 위주 도로패턴을 고려한다":"접근 위주 도로패턴과 곡선형 도로로의 감속 유도, 과속방지턱 설치를 고려합니다.","과속 시 차량에 상처·요동을 일으키려는 목적은 아니다":"차량에 상처나 요동을 일으키려는 것은 과속 시 목적이 아닙니다.","관리청은 도지사(특별시·광역시 구간은 시장)다":"도지사가 국가지원지방도 관리청이며 특별시·광역시 구간은 시장이 맡습니다.","관할구청장이 통행금지·제한 권한을 갖는 것은 아니다":"통행금지·제한 권한을 갖는 사람은 관할구청장이 아닙니다.","광역계획권의 공간적 범위와 개발 자체는 내용이 아니라 지정 기준이다":"광역계획권의 공간적 범위와 개발 자체는 지정 기준이며 내용이 아닙니다.","광역도시계획·도시기본계획에 부합해야 하며 계획도서·설명서를 작성한다":"도시관리계획은 광역도시계획과 도시기본계획에 부합해야 하며 계획도서와 설명서를 작성합니다.","광장에 교통시설을 집중시키는 다목적 계획이 원칙은 아니다":"다목적 계획이라며 교통시설을 광장 한 곳에 집중시키는 것이 원칙은 아닙니다.","광장은 만남의 공간이며 공간시설에는 광장·공원·녹지·유원지·공공공지가 있다":"광장, 공원, 녹지, 유원지, 공공공지가 공간시설이며 광장은 만남의 공간입니다.","교각이 작으면 곡선반지름이 작아 보이는 착각을 피하도록 한다":"교각이 작으면 곡선반지름이 작아 보이는 착각이 생기지 않게 해야 합니다.","교차각은 45도 이상으로 하고 건널목 양측 30m는 직선으로 한다":"건널목 양측 30m는 직선으로 하고 교차각은 45도 이상으로 합니다.","교차로 내 사고는 주로 직각충돌 사고가 많다":"직각충돌 사고가 교차로 내 사고에서 주로 많이 나타납니다.","교차로 부근 100m 이내에 버스정류장이 없어야 하는 것은 이상적 조건이 아니다":"이상적 조건에 교차로 부근 100m 이내 버스정류장 부재는 들지 않습니다.","교차로 부근 주차와 주차회전수가 많으면 사고가 늘고 완전출입제한은 사고감소에 효과적이다":"완전출입제한은 사고감소에 효과적이며 교차로 부근 주차와 주차회전수가 많으면 사고가 늘어납니다.","교차로 평면화계획은 연차별시행계획에 포함되지 않는다":"연차별시행계획에 교차로 평면화계획은 들지 않습니다.","교차로 폭원, 횡단 보행자수, 보행자 속도가 횡단시간 결정요소다":"횡단시간은 교차로 폭원, 횡단 보행자수, 보행자 속도로 결정합니다.","교차로·횡단보도·건널목, 교차로 가장자리 5m 이내, 안전지대 사방 10m 이내가 정차금지다":"교차로 가장자리 5m 이내와 안전지대 사방 10m 이내, 교차로·횡단보도·건널목에서는 정차할 수 없습니다.","교차점광장, 역전광장, 주요시설광장으로 구분된다":"교통광장은 교차점광장, 역전광장, 주요시설광장으로 나뉩니다.","교통광장, 경관광장, 지하광장 등이 광장 종류이며 상징적 광장 계획이 필요하다":"광장 종류에는 교통광장, 경관광장, 지하광장 등이 있고 상징적 광장 계획이 필요합니다.","교통량(q)은 속도(u)와 밀도(k)의 곱이다":"교통량은 속도에 밀도를 곱한 값입니다.","교통량 3000대/h, 평균속도 20km/h이면 밀도는 75대/km/차로, 차두간격은 2.4초/대다":"밀도 75대/km/차로와 차두간격 2.4초/대는 교통량 3000대/h, 평균속도 20km/h에서 나오는 값입니다.","교통량과 통행시간을 동시에 수집하며 유사한 연속구간에 적용한다":"유사한 연속구간에 적용하며 교통량과 통행시간을 동시에 수집하는 것이 이동측정법입니다.","교통량이 많은 곳 설치는 설치 기준이 아니다":"설치 기준에 교통량이 많은 곳은 들지 않습니다.","교통량이 조금만 늘거나 혼란이 있어도 와해 상태가 된다":"서비스수준 E는 교통량이 조금만 늘거나 혼란이 있어도 와해 상태가 됩니다.","교통류는 직진이며 모두 승용차로 구성, 경사 없는 접근로가 이상적 조건이다":"이상적 조건은 교통류가 직진이며 모두 승용차로 구성되고 경사 없는 접근로입니다.","교통류율의 역수이며 앞뒤차의 통과시간 차이다":"차두시간은 교통류율의 역수이며 앞뒤 차가 통과하는 시간의 차이입니다.","교통발생량은 토지이용 용도배분에 따라 다르며 집약적일수록 교통시설량이 늘어난다":"집약적일수록 교통시설량이 늘며 교통발생량은 토지이용 용도배분에 따라 다릅니다.","교통사고 감소, 용량 증대, 상충이동류 감소가 일방통행의 장점이다":"일방통행의 장점은 교통사고 감소, 용량 증대, 상충이동류 감소입니다.","교통사고로 인한 소통 문제구간 파악은 상충조사의 목적이 아니다":"소통 문제구간 파악은 상충조사 목적이 아니며 교통사고로 인한 것도 해당하지 않습니다.","교통사고 예방으로 생명·재산 보호는 이 법의 목적이 아니다":"생명·재산 보호를 위한 교통사고 예방은 이 법의 목적에 들지 않습니다.","교통사고 유발인자 3가지는 도로사용자·차량·환경이고 교통정책은 아니다":"교통정책은 교통사고 유발인자가 아니며 도로사용자, 차량, 환경이 세 가지 유발인자입니다.","교통수단 범위에 포함되지 않는다":"원동기장치자전거는 교통수단 범위에 포함되지 않습니다.","교통수단·체계의 효율적 운영·관리, 교통시설 정비 촉진, 소통·편의 증진이 목적이다":"소통·편의 증진과 교통시설 정비 촉진, 교통수단·체계의 효율적 운영·관리가 목적입니다.","교통시간 단축으로 교통문제 해결을 목표로 1882년 마타가 제안했다":"선상도시는 교통시간 단축으로 교통문제를 해결하려고 1882년 마타가 제안했습니다.","교통시설 개선, 대중교통체계 개선, 환경친화적 교통체계 구축을 포함한다":"환경친화적 교통체계 구축과 교통시설 개선, 대중교통체계 개선이 포함 내용입니다.","교통시설은 도로·주차장·철도·공항·환승시설이며 교통체계관리는 효율 극대화 행위다":"효율 극대화 행위가 교통체계관리이며 교통시설은 도로, 주차장, 철도, 공항, 환승시설입니다.","교통신호체계 개선, 버스전용차로·정류장 설치, 진출입 동선 변경이 개선 조치다":"개선 조치로 꼽는 것은 교통신호체계 개선, 버스전용차로·정류장 설치, 진출입 동선 변경입니다.","교통안전기본계획은 10년이 아니라 5년마다 수립한다":"5년마다 수립하는 교통안전기본계획은 10년 주기가 아닙니다.","교통안전시설 개선·제한, 장비·차량 개선·제한, 근무환경 개선이 진단 후 조치다":"진단 후 조치로는 교통안전시설 개선·제한, 장비·차량 개선·제한, 근무환경 개선이 있습니다.","교통안전시설 확충, 환승시설 확충, 대중교통 개선이 포함된다":"연차별시행계획에는 교통안전시설 확충, 환승시설 확충, 대중교통 개선이 포함됩니다.","교통안전진단, 교통안전관리자 구분, 자격취소 권한 위임 등을 규정한다":"이 규정이 다루는 내용은 교통안전진단, 교통안전관리자 구분, 자격취소 권한 위임 등입니다.","교통운영의 기본요건 검토가 결함·개선책을 살피는 단계다":"결함과 개선책을 살피는 단계에서는 교통운영의 기본요건을 검토합니다.","교통정리 없는 교차로, 도로가 구부러진 부근, 비탈길 고갯마루 부근이 서행 장소다":"비탈길 고갯마루 부근과 교통정리 없는 교차로, 구부러진 도로 부근에서는 서행해야 합니다.","교통 존에 관련된 자료는 기초자료 3종에 포함되지 않는다":"기초자료 3종에 교통 존에 관련된 자료는 들지 않습니다.","교통처리계획, 가구·획지규모 조성계획, 건축물 배치·형태·색채·건축선이 지구단위계획 내용이다":"지구단위계획 내용은 교통처리계획, 가구·획지규모 조성계획, 건축물 배치·형태·색채·건축선입니다.","교통통제는 용량증대 대책으로 추진하고 사전·사후 효과측정을 해야 한다":"사전·사후 효과측정을 하며 교통통제를 용량증대 대책으로 추진합니다.","교통통제설비 감소는 일방통행제 장점이 아니다":"일방통행제의 장점으로 교통통제설비 감소를 꼽을 수 없습니다.","구간 내 모든 차가 동일속도면 둘은 같으며 공간평균속도는 지점속도와 뜻이 다르다":"구간 내 모든 차가 같은 속도면 두 평균속도가 같고, 공간평균속도는 지점속도와 뜻이 다릅니다.","구간별 통행시간, 도로용량, 기종점 통행량이 통행배정 자료다":"기종점 통행량, 구간별 통행시간, 도로용량이 통행배정에 필요한 자료입니다.","구경꾼이 모이지 않게 하고 조사장비·관찰자를 운전자에게 숨긴다":"조사장비와 관찰자를 운전자에게 숨기고 구경꾼이 모이지 않게 합니다.","구름저항은 타이어-노면 마찰, 곡선저항은 곡선 주행, 공기저항은 버스·트럭이 더 크다":"공기저항은 버스·트럭이 더 크고 구름저항은 타이어-노면 마찰, 곡선저항은 곡선 주행에서 생깁니다.","국가기간 교통시설에 포함되지 않는다":"광역복합환승센터는 국가기간 교통시설에 포함되지 않습니다.","국가기간복합환승센터, 국가지원지방도, 일반국도대체우회도로가 국가기간교통시설이다":"국가기간교통시설에는 국가기간복합환승센터, 국가지원지방도, 일반국도대체우회도로가 속합니다.","국가방위, 지역균형발전, 도시화 촉진·도시연결이 교통의 기능이다":"교통의 기능에는 국가방위, 지역균형발전, 도시화 촉진·도시연결이 있습니다.","국도 등 주요 도로와의 교차·접근 지점에 배치한다":"주요 도로인 국도 등과 만나거나 가까워지는 지점에 배치합니다.","국도의 관리청은 건설교통부장관이다":"건설교통부장관이 국도의 관리청입니다.","국민복지 향상과 국토환경 보존, 남북통일 대비 기반 조성도 목표다":"남북통일 대비 기반 조성과 국민복지 향상, 국토환경 보존도 목표입니다.","국지도로·집산도로·보조간선도로는 일반도로이고 고속도로는 아니다":"고속도로는 일반도로가 아니고 국지도로, 집산도로, 보조간선도로가 일반도로입니다.","국토계획→지역계획→도시계획→단지계획 순이다":"공간계획은 국토계획, 지역계획, 도시계획, 단지계획 순입니다.","국토교통부장관은 투자평가지침을 작성·고시해야 한다":"투자평가지침을 작성·고시하는 사람은 국토교통부장관입니다.","국토교통부장관이 전문가 참여 점검단을 구성·운영할 수 있다":"전문가가 참여하는 점검단을 구성·운영하는 일은 국토교통부장관이 할 수 있습니다.","국토이용계획에 적합하고 장래 인구·산업규모를 고려해야 한다":"장래 인구와 산업규모를 고려하고 국토이용계획에 적합해야 하는 것이 도시계획입니다.","군수·특별시장·특별자치도지사는 도시군기본계획 수립권자이고 면장은 아니다":"면장은 도시군기본계획 수립권자가 아니며 군수, 특별시장, 특별자치도지사가 수립권자입니다.","굴곡부는 자동차가 5m 이상 내변반경으로 회전 가능해야 한다":"5m 이상 내변반경으로 자동차가 회전할 수 있어야 굴곡부로 인정합니다.","규제표지가 위험물 안내인 것은 아니다(그건 주의표지)":"규제표지가 위험물 안내인 것은 아니고 그것은 주의표지입니다.","규제표지의 모양은 원형이며 사각형은 아니다":"규제표지는 사각형이 아니라 원형입니다.","균일성장률법·Detroit모형·평균성장률법은 성장률법이고 Gravity법은 아니다":"Gravity법은 성장률법이 아니며 균일성장률법, Detroit모형, 평균성장률법이 성장률법입니다.","균일성장률법·프라타법·퍼네스법은 성장률법에 포함되고 중력모델은 아니다":"균일성장률법, 프라타법, 퍼네스법은 성장률법이고 중력모델은 성장률법이 아닙니다.","균일지체, 증분지체, 추가지체가 서비스수준 분석 지체이고 상관지체는 아니다":"상관지체는 서비스수준 분석 지체가 아니며 균일지체, 증분지체, 추가지체가 해당합니다.","그 3분류에 포함되지 않는다":"개량재개발은 그 세 가지 분류에 포함되지 않습니다.","근린상업·유통상업·일반상업지역은 상업지역 분류이고 노선상업지역은 아니다":"노선상업지역은 상업지역 분류가 아니며 근린상업, 유통상업, 일반상업지역이 분류입니다.","금고 이상 실형 집행종료 1년 경과자, 집행유예 중인 자, 한정치산자는 될 수 없다":"집행유예 중인 자와 한정치산자, 금고 이상 실형 집행종료 후 1년이 지난 자는 결격사유입니다.","기계식은 램프·통로가 불필요하며 도심지에 주로 설치된다":"램프·통로가 필요 없는 기계식은 도심지에 주로 설치합니다.","기계식 주차장치를 설치한 노외·부설주차장이며 주차단위구획은 자동차 1대의 구획이다":"주차단위구획은 자동차 1대의 구획이며 기계식 주차장치를 설치한 노외·부설주차장이 기계식주차장입니다.","기동성 향상, 교통사고 감소, 에너지 절약이 교통정책 상위목표다":"교통정책의 상위목표는 기동성 향상, 교통사고 감소, 에너지 절약입니다.","기반부문, 상업(서비스)부문, 가계부문이 라우리모형의 공간구조 분류 항목이다":"라우리모형의 공간구조 분류 항목은 기반부문, 상업(서비스)부문, 가계부문입니다.","기본계획 20년, 중기계획 5년, 연차별시행계획 3년 주기로 수립한다":"연차별시행계획은 3년, 중기계획은 5년, 기본계획은 20년 주기로 수립합니다.","기본계획 수립·변경·평가, 개선명령 실시계획, 교통수요관리 시행이 지방위원회 업무다":"지방위원회 업무는 기본계획 수립·변경·평가, 개선명령 실시계획, 교통수요관리 시행입니다.","기존도로를 효율적으로 활용하나 설치·운영이 간단한 것은 아니다":"설치·운영이 간단하지 않은 가변차로제는 기존도로를 효율적으로 활용합니다.","기존 버스노선 운행 효율성은 감소할 수 있으나 승객이 느는 것은 아니다":"승객이 느는 것은 아니며 기존 버스노선의 운행 효율성은 줄 수 있습니다.","긴급자동차는 앞지르기 금지장소를 무시해 앞지를 수 있으며 부득이하면 정지하지 않을 수 있다":"앞지르기 금지장소를 무시해 앞지를 수 있고 부득이하면 정지하지 않을 수 있는 것이 긴급자동차입니다.","긴급자동차는 정지·서행 중인 다른 차 앞에 끼어들 수 있고 제한속도를 초과해 운행할 수 있다":"정지·서행 중인 다른 차 앞에 끼어들 수 있고 제한속도를 초과해 운행할 수 있는 것이 긴급자동차입니다.","길어깨는 고장차 대피, 차도 폭원 보전, 노상시설 설치를 위해 설치한다":"고장차 대피, 차도 폭원 보전, 노상시설 설치가 길어깨를 설치하는 이유입니다.","길어깨는 도로 미관을 높이고 곡선부에서 시거를 늘려 안전성을 높인다":"곡선부 시거를 늘려 안전성을 높이고 도로 미관을 높이는 것이 길어깨의 효과입니다.","길어깨를 줄이는 장대교·터널에는 비상주차대를 적당한 간격으로 설치한다":"비상주차대는 길어깨를 줄이는 장대교와 터널에 적당한 간격으로 설치하는 시설입니다.","난간 높이는 1m 이상, 폭은 10cm 이상이다":"난간은 높이를 1m 이상, 폭을 10cm 이상으로 합니다.","낮은 속도에서는 저항이 적고 완만하게 통과하도록 하며 연속형은 20~90m 간격이다":"연속형은 20~90m 간격이며, 낮은 속도에서는 저항이 적고 완만하게 통과하도록 합니다.","내리막 구간, 급커브 구간, 횡단보도 전방에 미끄럼방지포장을 시공한다":"미끄럼방지포장은 급커브 구간, 내리막 구간, 횡단보도 전방에 시공합니다.","내부수익률(IRR), 편익비용비(B/C), 순현재가치(NPV)가 경제성 평가 지표다":"경제성 평가 지표에는 내부수익률(IRR), 편익비용비(B/C), 순현재가치(NPV)가 있습니다.","내부수익률·순현재가치·편익비용비는 경제적 효율성 분석법이고 비용효과분석은 아니다":"비용효과분석은 경제적 효율성 분석법이 아니며 내부수익률, 순현재가치, 편익비용비가 분석법입니다.","너비 2.0m·길이 3.6m":"경형 주차구획은 너비 2.0m, 길이 3.6m입니다.","너비 2.5m·길이 5.0m가 기준이다":"일반형 주차구획은 너비 2.5m, 길이 5.0m가 기준입니다.","너비 2.6m·길이 5.4m인 것은 아니다(5.2m가 기준)":"확장형은 너비 2.6m, 길이 5.4m인 것이 아니고 길이 5.2m가 기준입니다.","너비 3.3m, 길이 5.0m가 기준이다":"장애인전용 주차구획은 너비 3.3m, 길이 5.0m가 기준입니다.","너비 3.3m·길이 6.0m 이상이 기준이다":"장애인전용 주차구획은 너비 3.3m, 길이 6.0m 이상입니다.","노면 굴착·복구에 따른 경제적 손해와 지지력 손상을 막는다":"경제적 손해와 지지력 손상을 막아 주는 것은 노면 굴착·복구를 줄이기 때문입니다.","노면굴착에 의한 교통장애를 제거하나 관리자가 달라 개장 시기를 맞추기 어렵다":"관리자가 달라 개장 시기를 맞추기 어려우나 노면굴착에 의한 교통장애를 없앱니다.","노면의 내구력이 감소해 유지비가 느는 것은 아니다":"유지비가 느는 원인이 노면 내구력의 감소는 아닙니다.","노면의 마찰계수와 밀접한 관계가 있다":"정지시거는 노면의 마찰계수와 밀접한 관계가 있습니다.","노면의 스키드마크로 제동거리를 구할 수 있다":"스키드마크가 노면에 남아 있으면 이를 이용해 제동거리를 구할 수 있습니다.","노면 재질변경, 시각적 폭 좁힘, 노면 스트립이 도로환경 개선대책이다":"도로환경 개선대책에는 노면 재질변경, 시각적 폭 좁힘, 노면 스트립이 있습니다.","노선·수입금·차량 공동관리제가 공동배차제 유형이고 운전자공동관리는 아니다":"운전자공동관리는 유형이 아니며 노선, 수입금, 차량 공동관리제가 공동배차제 유형입니다.","노인·아동시설 출입구 20m 이내, 너비 4m 미만 도로는 출입구 설치금지 장소다":"너비 4m 미만 도로나 노인·아동시설 출입구 20m 이내는 출입구 설치금지 장소입니다.","녹색시간도 길어져 차두시간이 늘고 용량증대효과가 상쇄될 수 있다":"차두시간이 늘 만큼 녹색시간도 길어져 용량증대효과가 상쇄될 수 있습니다.","녹색시간 설계 고려사항이 아니다":"차량 속도는 녹색시간 설계 고려사항이 아닙니다.","녹지·계획관리지역, 지구단위계획구역, 기반시설부담구역은 개발행위허가 제한 가능 지역이다":"개발행위허가를 제한할 수 있는 지역은 녹지·계획관리지역, 지구단위계획구역, 기반시설부담구역입니다.","녹지관리체계·환경보전, 광역시설 배치·규모, 문화·여가·방재가 포함 내용이다":"문화·여가·방재, 광역시설 배치·규모, 녹지관리체계·환경보전이 포함 내용입니다.","녹지지역 내 10일 이상 물건 적치는 허가 대상이 아니다(1개월 이상이 기준)":"물건 적치는 녹지지역 내 10일 이상이 아니라 1개월 이상이 허가 기준입니다.","높이 2m 초과 시 계단참을 설치하며 난간 80cm·폭 5cm 기준은 아니다":"난간 80cm·폭 5cm 기준이 아니며 높이 2m 초과 시 계단참을 설치합니다.","높이는 주차바닥면에서 2.3m 이상이다":"주차바닥면에서 2.3m 이상의 높이를 확보합니다.","다른 사용자에 영향받지 않는다":"서비스수준 A는 다른 사용자에게 영향받지 않는 상태입니다.","다른 시설과 교차 시 입체교차가 원칙이다":"다른 시설과 교차할 때는 입체교차가 원칙입니다.","다양한 토지이용을 한 존에 섞지 않고 간선도로를 존 경계와 일치시킨다":"간선도로를 존 경계와 맞추고, 서로 다른 토지이용을 한 존에 섞지 않습니다.","다이아몬드형은 불완전 입체교차이다":"불완전 입체교차에 해당하는 형식이 다이아몬드형입니다.","단속 가능한 정도의 제한과 현장 여건에 맞는 제한이 사고를 줄인다":"단속할 수 있는 정도로 제한하고 현장 여건에 맞춰야 사고가 줄어듭니다.","단순 충격완화시설은 탑승자 생존, 비산 방지, 신속한 보수가 가능해야 한다":"신속한 보수가 가능하고 탑승자 생존과 비산 방지가 되어야 단순 충격완화시설입니다.","단순하고 이해하기 쉬우며 외부수요로 성장이 결정된다고 본다":"외부수요로 성장이 결정된다고 보는 경제기반모형은 단순하고 이해하기 쉽습니다.","단위 면적당 사고건수로 결정하지 않는다":"선형밀도법은 단위 면적당 사고건수로 결정하지 않습니다.","대규모 주거지역·위성도시·장래 도시화지역은 폐쇄선 안에 포함시킨다":"폐쇄선 안에는 대규모 주거지역, 위성도시, 장래 도시화지역을 넣습니다.","대량수송이 필요하고 단거리 교통이며 하루 2회 피크가 발생한다":"하루 2회 피크가 발생하고 단거리 교통이며 대량수송이 필요한 특성입니다.","대상사업 및 연계개발계획, 사업비·재원조달방안, 투자재원분담 기준이 계획에 포함된다":"사업비·재원조달방안과 투자재원분담 기준, 대상사업 및 연계개발계획을 계획에 담습니다.","대안 비교 기준을 제시하며 편익을 비용으로 나눈 비율로 선택하는 방법은 아니다":"편익을 비용으로 나눈 비율로 선택하는 방법이 아니며 대안 비교 기준을 제시합니다.","대안이 적고 교통수요가 비교적 고정돼 있다":"장기교통계획은 대안이 적고 교통수요가 비교적 고정되어 있습니다.","대안평가는 계획수립 과정의 한 단계다":"계획수립 과정을 이루는 한 단계가 대안평가입니다.","대중교통수단 육성, 자가용 통행금지구역 확대, 보행자전용도로 건설이 억제정책이다":"억제정책이라 부르는 것은 보행자전용도로 건설, 자가용 통행금지구역 확대, 대중교통수단 육성입니다.","대중교통 정보망 구축, 보행자전용지구 지정, 대중교통전용지구 지정이 시장의 시행 내용이다":"시장이 시행하는 내용은 대중교통 정보망 구축, 보행자전용지구 지정, 대중교통전용지구 지정입니다.","대지면적에 대한 건축면적의 비율이다":"건폐율은 대지면적에 대한 건축면적의 비율입니다.","대지에 건축물이 둘 이상이면 큰 건축물 면적만 적용하는 것은 아니다":"둘 이상의 건축물이 있는 대지에서 큰 건축물 면적만 적용하는 방식은 아닙니다.","대통령령으로 노선 지정하며 서울·부산시내 고속국도의 관리청은 시장이 아니다":"대통령령으로 노선을 지정하는 고속국도는 서울·부산시내 구간도 시장이 관리청이 아닙니다.","대형기계식주차장 출입구는 너비 2.4m 이상, 높이 1.6m 이상이다":"너비 2.4m 이상, 높이 1.6m 이상이 대형기계식주차장 출입구 기준입니다.","대형차 혼입율, 측방여유폭, 종단구배는 용량보정계수에 포함되고 차로수는 아니다":"차로수는 용량보정계수에 들지 않고 대형차 혼입율, 측방여유폭, 종단구배가 포함됩니다.","도로, 기념적 건조물, 지구가 5가지 이미지 요소이며 공간(space)은 아니다":"공간(space)은 이미지 요소가 아니며 도로, 기념적 건조물, 지구가 5가지에 속합니다.","도로 계획·설계·운영과 무관한 독립적인 사람이어야 한다":"도로 계획·설계·운영과 무관한 사람이 독립적으로 진단 주체가 되어야 합니다.","도로 고급화, 개선된 차량성능·조향장치가 이동성·안전성 동시 제고 조치다":"이동성과 안전성을 함께 높이는 조치는 도로 고급화, 개선된 차량성능, 조향장치입니다.","도로 곡선반경은 설계속도의 제곱에 정비례한다":"도로 곡선반경은 설계속도를 제곱한 값에 정비례하여 커집니다.","도로공사 구간 양쪽 가장자리 5m 이내도 주차금지다":"양쪽 가장자리 5m 이내에서는 도로공사 구간이라도 주차를 금지합니다.","도로교통법상 자동차·원동기장치자전거·긴급자동차와 차마, 철도 등을 포함하며 자전거만 제외하는 것은 아니다":"자전거만 제외하는 것은 아니며 자동차·원동기장치자전거·긴급자동차와 차마, 철도 등을 포함합니다.","도로 구간별 건설비는 통행배정 자료가 아니다":"통행배정 자료에 도로 구간별 건설비는 들지 않습니다.","도로노선·예정지 지정, 접도구역 지정, 건설재원·장기계획이 심의사항이다":"심의사항에는 도로노선·예정지 지정, 접도구역 지정, 건설재원·장기계획이 있습니다.","도로는 고속도로와 일반도로로 구분하며 도시지역 고속도로는 도시고속도로다":"도시지역 고속도로를 도시고속도로라 하며 도로는 고속도로와 일반도로로 구분합니다.","도로는 지역·시설을 연계하고 가구를 구획하며 위계적 구조를 갖는다":"가구를 구획하고 지역과 시설을 연계하며 위계적 구조를 갖는 것이 도로의 역할입니다.","도로를 횡단하는 보행자나 차마의 안전을 위한 곳이다":"도로를 횡단하는 보행자나 차마가 안전하도록 마련한 곳이 안전지대입니다.","도로를 효율적으로 이용하고 투자를 적절히 하기 위해 한다":"투자를 적절히 하고 도로를 효율적으로 이용하려고 용량분석을 합니다.","도로 문제지점의 기하설계요소 평가, 상충으로 사고위험성 평가가 목적이다":"상충조사는 도로 문제지점의 기하설계요소를 평가하고 상충으로 사고위험성을 평가하려는 것입니다.","도로 물리적 형상을 관련시키기 위해 정한 속도이며 기하구조 결정의 기본이다":"기하구조 결정의 기본이 되는 속도로, 도로 물리적 형상을 관련시키려고 정합니다.","도로 보호·비상시 이용을 위해 차도에 접속해 설치한 부분이다":"차도에 접속해 설치하여 도로를 보호하고 비상시 이용하게 한 부분이 길어깨입니다.","도로사용자 충돌 전 조치는 운전자교육, 충돌 후 조치는 비상의료서비스다":"충돌 후 조치는 비상의료서비스이고 충돌 전 도로사용자 조치는 운전자교육입니다.","도로상을 운행할 수 없는 것은 아니며 차량 중량이 가벼운 편이다":"차량 중량이 가벼운 편이고 도로상을 운행할 수 없는 것은 아닙니다.","도로 상태가 나쁠수록 회전저항이 크다":"회전저항은 도로 상태가 나쁠수록 커집니다.","도로·선박·항만하역교통안전관리자는 분야에 속하고 자동차교통안전관리자는 아니다":"자동차교통안전관리자는 분야에 속하지 않고 도로, 선박, 항만하역 교통안전관리자가 속합니다.","도로원표, 가로등, 이정표는 도로 부속물이고 도로터널은 아니다":"도로터널은 부속물이 아니며 도로원표, 가로등, 이정표가 도로 부속물입니다.","도로원표 설치기준은 국토교통부령으로 정하며 군에도 도로원표를 설치한다":"군에도 도로원표를 설치하며 설치기준은 국토교통부령으로 정합니다.","도로 위 차량의 평균속도를 뜻하는 것은 아니며 횡단경사는 직접 관계가 적다":"횡단경사는 설계속도와 직접 관계가 적으며 설계속도는 도로 위 차량의 평균속도를 뜻하지 않습니다.","도로의 구부러진 곳, 비탈길 고갯마루·내리막, 교차로·터널·다리 위가 금지장소다":"비탈길 고갯마루와 내리막, 교차로, 터널, 다리 위, 도로의 구부러진 곳이 금지장소입니다.","도로의 선형·노면상태·노폭은 도로구조요인이고 안전시설·운행차량구성은 아니다":"안전시설과 운행차량구성은 도로구조요인이 아니고, 도로의 선형, 노면상태, 노폭이 도로구조요인입니다.","도로이용자 행동특성을 고려하고 시인성을 방해하지 않으며 중요 표지를 집중 설치하지 않는다":"중요 표지는 집중 설치하지 않으며 도로이용자 행동특성을 고려해 시인성을 방해하지 않습니다.","도로이용 효율성 제고, 교통안전 도모, 환경 악영향 감소가 ITS 목적이다":"ITS의 목적은 도로이용 효율성 제고, 교통안전 도모, 환경 악영향 감소입니다.","도로·자동차정류장·삭도는 교통시설이고 화물적하시설은 아니다":"화물적하시설은 교통시설이 아니고 도로, 자동차정류장, 삭도가 교통시설입니다.","도로정비의 목표·방향, 정비·관리계획, 환경친화적 건설방안을 포함한다":"환경친화적 건설방안과 정비·관리계획, 도로정비의 목표·방향을 포함합니다.","도로주차공간 확보는 도류화 목적이 아니다":"도로주차공간 확보를 도류화 목적으로 삼지는 않습니다.","도로 측면 충돌 중 조치는 부러지는 지주 설치 등 노변안전조치다":"부러지는 지주 설치 등 노변안전조치가 도로 측면 충돌 중 조치입니다.","도로 파손 등으로 인한 위험방지 조치를 할 수 있다":"자치경찰공무원은 도로 파손 등으로 인한 위험방지 조치를 할 수 있습니다.","도로표식·이정표는 부속물이고 가로수·중앙분리대는 아니다":"가로수와 중앙분리대는 부속물이 아니고 도로표식과 이정표가 부속물입니다.","도로표지·관제시설 설치 공간을 제공하고 광폭이면 고장차량 대피공간이 된다":"광폭이면 고장차량 대피공간이 되고 도로표지·관제시설 설치 공간도 제공합니다.","도류로를 명시하고 보행자 안전섬 역할을 하며 부대시설 설치 장소를 제공한다":"보행자 안전섬 역할을 하고 도류로를 명시하며 부대시설 설치 장소를 제공합니다.","도류화, 회전유도차선 표지, 충분한 좌회전 신호현시가 대책이다":"충분한 좌회전 신호현시와 도류화, 회전유도차선 표지가 대책으로 꼽힙니다.","도보 횡단인의 수, 교차로 통과속도는 고려사항이 아니다":"교차로 통과속도와 도보 횡단인의 수는 고려사항에 들지 않습니다.","도시개발사업, 기업도시개발사업, 철도건설사업이 대중교통시설 반영 대상이다":"대중교통시설 반영 대상은 도시개발사업, 기업도시개발사업, 철도건설사업입니다.","도시계획은 목표설정→상황분석·예측→대안설정·평가→집행 순으로 진행한다":"도시계획은 목표설정에서 시작해 상황분석·예측, 대안설정·평가를 거쳐 집행으로 이어집니다.","도시미관 보호, 방재능률 향상, 도로교통 원활화가 공동구 설치 목적이다":"공동구는 도시미관 보호, 방재능률 향상, 도로교통 원활화를 위해 설치합니다.","도시성장의 동결은 성장관리의 목적이 아니다":"성장관리의 목적에 도시성장의 동결은 들어가지 않습니다.","도시적 기능의 급격한 집중, 경관 혼란, 획일화가 과대·과밀도시 문제다":"과대·과밀도시에서는 도시적 기능이 급격히 집중되고 경관이 혼란스러우며 획일화됩니다.","도시 전체에 걸쳐 통행이 균등하고 정시성이 약한 것은 아니다":"통행이 도시 전체에 균등하다거나 정시성이 약하다는 특성은 아닙니다.","도시 주위에 넓은 농업지대·녹지대를 가지며 공업기능을 배제하지 않는다":"전원도시는 도시 주위에 넓은 농업지대와 녹지대를 두며 공업기능을 배제하지 않습니다.","도시지역, 관리지역, 자연환경보전지역은 용도지역이고 준농림지역은 아니다":"준농림지역은 용도지역이 아니며 도시지역, 관리지역, 자연환경보전지역이 용도지역입니다.","도시지역 고속도로 100km, 주간선도로 80km, 보조간선도로 60km가 설계속도다":"100km는 도시지역 고속도로, 80km는 주간선도로, 60km는 보조간선도로에 정한 설계속도입니다.","도시지역 고속도로 중앙분리대는 2.0m, 지방지역 일반도로는 1.5m가 최소 기준이다":"중앙분리대 최소 기준은 도시지역 고속도로가 2.0m, 지방지역 일반도로가 1.5m입니다.","도시지역 고속도로 중앙분리대 표준폭은 일률적으로 1.0m가 아니다":"1.0m로 일률적으로 정해진 것이 아니라서 도시지역 고속도로 중앙분리대의 표준폭은 상황에 따라 달라집니다.","도시지역 일반도로의 주정차대(소형차 대상) 최소 폭은 2.5m다":"소형차 대상 주정차대는 도시지역 일반도로에서 최소 폭이 2.5m입니다.","도시지역 일반도로 중앙분리대 최소 폭은 1.0m다":"최소 폭은 도시지역 일반도로 중앙분리대의 경우 1.0m입니다.","도시지역 집산도로·지방지역 산지 보조간선도로·지방지역 평지 국지도로는 50km/h 이상이다":"지방지역 평지 국지도로와 산지 보조간선도로, 도시지역 집산도로는 50km/h 이상으로 봅니다.","도시철도 수송서비스의 편리성·안락도 증진은 직접편익에 해당한다":"수송서비스의 편리성·안락도가 도시철도에서 높아지는 것은 직접편익입니다.","도심 등 특정지역에 통행이 집중된다":"도심 등 특정지역으로 통행이 집중되는 특성이 있습니다.","도심부 터미널은 교통수요가 큰 곳에, 대도시는 부도심부에 설치해 집중을 막는다":"집중을 막으려고 대도시에서는 터미널을 부도심부에, 도심부에서는 교통수요가 큰 곳에 설치합니다.","도심 주차장 건설은 억제정책이 아니다":"억제정책으로 보지 않는 것이 도심 주차장 건설입니다.","도심 형성이 유리해 대도시에 적합하다는 것은 선상도시 특징이 아니다":"선상도시의 특징 가운데 대도시에 적합하다는 설명은 틀립니다.","도착간격 평균 0.5분, 음지수분포":"도착간격 평균이 0.5분이면 도착간격은 음지수분포를 따릅니다.","도청-시군청소재지 도로, 비행장·항만·역 연결도로가 지방도에 해당한다":"비행장·항만·역 연결도로와 도청-시군청소재지 도로는 지방도에 해당합니다.","도청소재지-시군청소재지, 시군청소재지 상호간을 잇는 도로다":"지방도는 도청소재지와 시군청소재지, 그리고 시군청소재지끼리를 잇는 도로입니다.","동시시스템, 교호시스템, 연속진행시스템이 연동신호 운영방법이다":"연동신호는 동시시스템, 교호시스템, 연속진행시스템으로 운영합니다.","동심원이론, 선형이론, 다핵심이론이 버제스·호이트·해리스가 주창한 이론이다":"버제스, 호이트, 해리스가 주창한 이론은 동심원이론, 선형이론, 다핵심이론입니다.","동일한 속도제한이 모든 도로·교통조건에 타당한 것은 아니다":"모든 도로와 교통조건에 같은 속도제한이 타당한 것은 아닙니다.","등차급수법·최소자승법·지수함수법은 과거추세법이고 집단생잔법·비교유추법은 아니다":"집단생잔법과 비교유추법은 과거추세법이 아니며 등차급수법, 최소자승법, 지수함수법이 과거추세법입니다.","등판(오르막) 차로 구간은 시공 대상이 아니다":"시공 대상에 등판(오르막) 차로 구간은 들지 않습니다.","램프식, 경사바닥식, 기계식으로 옥내주차장을 구분한다":"옥내주차장은 램프식, 경사바닥식, 기계식으로 구분합니다.","르코르뷔지에는 위성도시론 주창자가 아니다":"위성도시론 주창자에 르코르뷔지에는 들지 않습니다.","모든 노선을 함께 설치하는 것이 이용객 편의를 위한 것은 아니다":"이용객 편의를 위해 모든 노선을 함께 설치하는 것은 아닙니다.","모든 바퀴 중 가장 긴 미끄럼 길이로 한다":"직선미끄럼 거리는 모든 바퀴 중 가장 긴 미끄럼 길이로 정합니다.","목적통행을 수단통행으로 나눈 비가 환승비율을 뜻하는 것은 아니다":"환승비율은 목적통행을 수단통행으로 나눈 비라는 뜻이 아닙니다.","묘지공원·도시자연공원·어린이공원은 도시공원 유형이고 운동공원은 아니다":"운동공원은 도시공원 유형이 아니며 묘지공원, 도시자연공원, 어린이공원이 유형입니다.","무거운 축하중은 수막현상 증대 요인이 아니다":"축하중이 무겁다고 수막현상이 커지는 것은 아닙니다.","무통제 교차로, 양방향정지 교차로, 로터리식 교차로가 비신호교차로 종류다":"비신호교차로 종류는 무통제 교차로, 양방향정지 교차로, 로터리식 교차로입니다.","미관지구·고도지구·보존지구는 용도지구이고 재개발지구는 아니다":"재개발지구는 용도지구가 아니며 미관지구, 고도지구, 보존지구가 용도지구입니다.","미관지구는 중심지·역사문화·일반미관지구로 세분되고 가로미관지구는 아니다":"가로미관지구는 세분 항목이 아니며 중심지, 역사문화, 일반미관지구로 세분됩니다.","밀도가 0이면 교통류율도 0이고 임계밀도에서 교통류율이 최댓값이다":"교통류율은 밀도가 0이면 0이 되고 임계밀도에서 최댓값에 이릅니다.","밀도가 늘면 교통량은 증가 후 감소하며 혼잡밀도는 모든 움직임이 정지한 상태다":"교통량은 밀도가 늘면 증가하다가 감소하며 혼잡밀도는 모든 움직임이 정지한 상태의 밀도입니다.","밀도가 증가하면 평균속도는 감소하며 임계밀도에서 속도가 최대인 것은 아니다":"평균속도는 밀도가 증가하면 감소하고, 임계밀도에서 속도가 최대가 되는 것은 아닙니다.","밀도·배치·동선은 도시구성의 3대 물리적 요소이고 정비는 아니다":"정비는 도시구성 요소가 아니며 밀도, 배치, 동선이 3대 물리적 요소입니다.","바닥재는 내수성·내구성·내마모성이 있어야 하며 미끄러운 면이면 안 된다":"내수성, 내구성, 내마모성이 있어야 하며 미끄러운 면은 안 되는 것이 바닥재 조건입니다.","반복된 노면굴착을 배제해 교통소통과 미관에 유리하다":"교통소통과 미관에 유리한 것은 반복된 노면굴착을 배제하기 때문입니다.","반사형·흡음형으로 구분되고 생태통로는 야생동물 서식지 단절을 줄인다":"생태통로는 야생동물 서식지 단절을 줄이고 방음벽은 반사형과 흡음형으로 구분합니다.","반응속도가 빨라도 제동거리는 줄이지 못한다":"제동거리는 반응속도가 빨라진다고 줄지 않습니다.","반응시간, 감속도, 접근속도가 황색신호 결정 주요 요인이다":"황색신호는 반응시간, 감속도, 접근속도가 주요 결정 요인입니다.","반응시간은 민감도로 결정되며 민감도가 크면 교통류가 불안정해지고 미시적 이론이다":"민감도로 반응시간이 정해지며, 민감도가 크면 교통류가 불안정해지는 미시적 이론입니다.","반응시거는 시거의 종류가 아니다":"시거의 종류에 반응시거는 들지 않습니다.","발전과정·현재기능 파악, 당면문제 해결방안 모색을 위해 수행한다":"기초조사는 발전과정과 현재 기능을 파악하고 당면문제 해결방안을 찾으려고 합니다.","방향전환 지점은 균형·조화를 이루고 충분한 시거를 확보해야 한다":"충분한 시거를 확보하고 균형·조화를 이루도록 방향전환 지점을 정합니다.","방호울타리, 자동차주차장, 도로수선용재료적치장은 부속물이고 제방·호안은 아니다":"제방과 호안은 부속물이 아니며 방호울타리, 자동차주차장, 도로수선용재료적치장이 부속물입니다.","방호책은 도로이탈을 막고 진행방향을 복원시키며 시선을 유도하나 보행자 보호는 아니다":"보행자 보호용은 아니고 도로이탈을 막으며 진행방향을 복원시키고 시선을 유도하는 것이 방호책의 역할입니다.","배기량 기준이 있으며 이륜자동차 전체를 뜻하지 않는다":"이륜자동차 전체를 뜻하지 않고 배기량 기준이 있는 것이 원동기장치자전거입니다.","백색이 정차금지표시, 녹색이 동일방향 분리를 뜻하는 것은 아니다":"정차금지표시를 백색으로, 동일방향 분리를 녹색으로 뜻하는 것은 아닙니다.","버스운행관리시스템, 버스전용차로, 교차로 버스우선통행이 BRT 구성요소다":"BRT 구성요소는 버스운행관리시스템, 버스전용차로, 교차로 버스우선통행입니다.","버스전용도로를 HOV차로로 전환하면 다인승 차량 통행시간이 줄고 주변 정체가 완화된다":"다인승 차량 통행시간이 줄고 주변 정체가 완화되는 것이 버스전용도로의 HOV차로 전환 효과입니다.","버스 정차대 규모 조정은 야간사고 개선대책이 아니다":"야간사고 개선대책에 버스 정차대 규모 조정은 들지 않습니다.","번호판 판독법, 시험차량 운행법, 주행차량 이용법은 구간속도 조사법이고 노측면접법은 아니다":"노측면접법은 구간속도 조사법이 아니며 번호판 판독법, 시험차량 운행법, 주행차량 이용법이 조사법입니다.","변속차로 폭은 2.75m 이상이며 2.5m 이상은 기준이 아니다":"2.5m 이상은 기준이 아니며 변속차로 폭은 2.75m 이상입니다.","병원·백화점·방송국은 시설면적 150㎡당 1대 설치 기준이다":"시설면적 150㎡당 1대를 설치하는 대상에는 병원, 백화점, 방송국이 있습니다.","보도, 아케이드, 보행자전용도로가 평면분리방식이다":"평면분리방식에는 보도, 아케이드, 보행자전용도로가 있습니다.","보도·차도가 구분 안 된 도로에서 보행자 안전을 위한 구역이다":"길가장자리구역은 보도와 차도가 구분되지 않은 도로에서 보행자 안전을 위한 구역입니다.","보도 통행금지 시나 보도가 없으면 길가장자리로 통행할 수 있다":"보도가 없거나 보도 통행금지 시에는 길가장자리로 통행할 수 있습니다.","보조간선도로에서 본선 혼란 우려가 있으면 버스정류장을 설치한다":"본선 혼란 우려가 있는 보조간선도로에는 버스정류장을 설치합니다.","보존녹지는 기능별 녹지 종류에 포함되지 않는다":"기능별 녹지 종류에 보존녹지는 들지 않습니다.","보차 미분리 도로에서 반드시 우측으로만 통행하는 것은 아니다":"우측 통행만 해야 한다는 규정은 보차 미분리 도로에서 반드시 적용되지는 않습니다.","보차 미분리 도로 중 보행자 사고 위험이 있는 곳에도 설치한다":"보행자 사고 위험이 있는 보차 미분리 도로에도 설치합니다.","보행교통류율·점유공간·밀도, 대기공간은 보행점유공간이 효과척도다":"보행자도로의 효과척도는 보행교통류율, 점유공간, 밀도, 대기공간과 관련 있습니다.","보행교통 유치는 길어깨의 목적이 아니다":"길어깨를 설치하는 목적에 보행교통 유치는 들지 않습니다.","보행자가 많은 곳에 적합하고 구조가 간단하며 설치비가 싸다":"고정식 신호는 구조가 간단하고 설치비가 싸서 보행자가 많은 곳에 적합합니다.","보행자는 차 앞뒤 횡단을 금지하되 횡단보도·신호 지시는 예외다":"횡단보도나 신호 지시가 있으면 예외이며 보행자는 차 앞뒤 횡단을 금지합니다.","보행자데크는 평면분리방식이 아니라 입체분리방식이다":"평면분리방식이 아니라 입체분리방식에 속하는 것이 보행자데크입니다.","보행자 안전지대, 교통통제설비 설치 장소를 제공한다":"도류화는 보행자 안전지대와 교통통제설비를 설치할 장소를 마련해 줍니다.","보행자 횡단 안전성을 높이고 좌회전차로 설치에 도움이 되며 대향차로 오인을 막는다":"대향차로 오인을 막고 좌회전차로 설치에 도움이 되며 보행자 횡단 안전성을 높입니다.","보행자 횡단은 안전지대 설치, 야간사고는 네온사인 제한, 시거불량은 시선유도표지로 대응한다":"안전지대 설치로 보행자 횡단에, 네온사인 제한으로 야간사고에, 시선유도표지로 시거불량에 대응합니다.","복잡해도 의미만 전달하면 되는 것은 아니다":"의미만 전달하면 되므로 복잡해도 된다는 설명은 틀립니다.","복합곡선·배향곡선·클로소이드곡선은 평면곡선이고 2차포물선은 아니다":"2차포물선은 평면곡선에 들지 않고 복합곡선, 배향곡선, 클로소이드곡선이 평면곡선입니다.","본선 도로 우측에 설치하는 것이 원칙이다":"긴급제동시설은 본선 도로 우측에 설치하는 것이 원칙입니다.","분류상충, 합류상충, 교차상충이 평면교차로 상충 종류다":"평면교차로 상충 종류에는 분류상충, 합류상충, 교차상충이 있습니다.","분명하고 다양한 의미를 지녀야 하는 것은 아니다(단순 명료해야 함)":"단순 명료해야 하며 분명하고 다양한 의미를 지녀야 하는 것은 아닙니다.","분석기간은 충분한 사고자료를 제공할 만큼 길어야 하며 공사 중 기간은 제외한다":"사고자료를 충분히 얻을 만큼 분석기간이 길어야 하며 공사 중 기간은 뺍니다.","분석기간이 짧을수록 정확한 것은 아니다":"정확도는 분석기간이 짧을수록 높아지는 것이 아닙니다.","비가 20mm 이상 내린 것은 50% 감속 기준이 아니다":"50% 감속 기준에서 비가 20mm 이상 내린 경우는 제외됩니다.","비 오는 날은 제동거리가 길어지며 노면·타이어 상태와 관계있다":"비 오는 날은 노면과 타이어 상태 때문에 제동거리가 길어집니다.","비용부담의 원칙, 원인자부담금, 손궤자부담금이 도로 비용·수익 관련 원칙이다":"도로 비용·수익 관련 원칙은 비용부담의 원칙, 원인자부담금, 손궤자부담금입니다.","비탈면 경사는 접속 도로와 동일하거나 완만하게 하며 접속부 곡선반경은 15m 이상이다":"접속부 곡선반경은 15m 이상이고 비탈면 경사는 접속 도로와 같거나 완만하게 합니다.","빈도수가 가장 많은 속도범위이며 중앙값이 항상 50% 속도와 일치하지는 않는다":"빈도수가 가장 많은 속도범위가 최빈 속도이며 중앙값이 항상 50% 속도와 같은 것은 아닙니다.","사고 100건당 사망자 수를 뜻한다":"치사율은 사고 100건당 사망자 수를 뜻합니다.","사고 많은 장소 선별, 원인분석을 통한 방지대책·책임규명이 목적이다":"원인분석을 통한 방지대책·책임규명과 사고 많은 장소 선별이 목적입니다.","사고율법, 사고건수법, 율-품질관리법은 위험지점 선정 기법이고 사고위험율법은 아니다":"사고위험율법은 위험지점 선정 기법이 아니며 사고율법, 사고건수법, 율-품질관리법이 선정 기법입니다.","사고율법은 교통량 대비, 한계사고율법은 유사지역 평균과 비교하는 방법이다":"사고율법은 교통량 대비로, 한계사고율법은 유사지역 평균과 비교하여 위험지점을 고릅니다.","사고율은 MEV당 사고율을 쓰며 사고건수가 포아송분포를 따른다고 가정한다":"사고건수가 포아송분포를 따른다고 가정하여 MEV당 사고율을 씁니다.","사고자료 수집·정리, 위험지역 공학적 분석, 시행 우선순위 결정이 계획단계 작업이다":"계획단계 작업은 사고자료 수집·정리, 위험지역 공학적 분석, 시행 우선순위 결정입니다.","사고 집중지점의 신속한 시각적 색인을 제공하며 범례는 단순해야 한다":"범례를 단순하게 하여 사고가 집중된 지점을 신속하게 시각적으로 색인할 수 있게 합니다.","사고패턴 파악과 개선책 분석에 쓰이며 축척을 무시해 작도한다":"충돌도는 사고패턴을 파악하고 개선책을 분석하는 데 쓰이며 축척을 무시해 작도합니다.","사람통행과 평균승차인원을 고려해 주차수요를 추정한다":"P요소법은 사람통행과 평균승차인원을 고려해 주차수요를 추정하는 방법입니다.","사업면적 110만㎡ 택지개발, 시설계획지구 200만㎡ 관광단지조성이 대상사업에 해당한다":"택지개발 사업면적 110만㎡, 관광단지조성 시설계획지구 200만㎡가 대상사업에 해당합니다.","사업시행 예비타당성 평가는 교통영향평가 내용이 아니다":"교통영향평가 내용에 사업시행 예비타당성 평가는 들지 않습니다.","사업시행자는 사업 시작 전 투자평가지침에 따라 타당성을 평가해야 한다":"투자평가지침에 따라 사업 시작 전 타당성을 평가해야 하는 사람은 사업시행자입니다.","사업의 수익성을 측정하고 평가과정·결과를 이해하기 쉽다":"사업의 수익성을 재고 평가과정과 결과를 이해하기 쉽다는 것이 이 지표의 장점입니다.","사업의 절대적 규모는 고려하지 못한다":"이 지표는 사업의 절대적 규모를 고려하지 못하는 한계가 있습니다.","사용자균형에서 선택된 모든 경로의 통행시간은 동일하다":"사용자균형에서는 선택된 모든 경로의 통행시간이 같습니다.","사회·경제적 지위에 따른 주거적 토지이용을 특징으로 한다":"주거적 토지이용이 사회·경제적 지위에 따라 정해지는 것이 특징입니다.","사회경제 지표현황, 자동차 보유현황, 토지이용현황을 조사한다":"토지이용현황, 자동차 보유현황, 사회경제 지표현황을 조사합니다.","사회적 이용가치, 시장가치, 생태적 가치가 토지이용의 3대 가치다":"토지이용의 3대 가치는 사회적 이용가치, 시장가치, 생태적 가치입니다.","상관분석은 두 변수 관계의 밀접도를, 회귀분석은 독립·종속변수 선형관계를 구한다":"독립·종속변수의 선형관계를 구하는 회귀분석과 달리 상관분석은 두 변수 관계의 밀접도를 구합니다.","상대속도를 줄이고 회전교통경로를 마련하며 상충면적을 줄인다":"상충면적을 줄이고 회전교통경로를 마련하며 상대속도를 낮추는 것이 목표입니다.","상대적 접근성으로 결정되며 기회 선택확률은 일정하다고 가정한다":"기회 선택확률을 일정하다고 가정하고 목적지는 상대적 접근성으로 정합니다.","상시조사는 연간 일정 간격으로 연속 7일씩 시간별 교통량을 측정한다":"연간 일정 간격으로 연속 7일씩 시간별 교통량을 측정하는 조사가 상시조사입니다.","상업·공업지역의 토지 효율적 이용을 위한 사업이다":"도시환경정비사업은 상업·공업지역의 토지를 효율적으로 이용하려는 사업입니다.","상업지역 노상주차장을 인근주민용으로 쓰는 것은 전용구획 대상이 아니다":"인근주민용으로 상업지역 노상주차장을 쓰는 것은 전용구획 대상이 아닙니다.","상충교통류 증가는 일방통행의 효과가 아니다":"일방통행의 효과에 상충교통류 증가는 들지 않습니다.","상충면적은 좁게, 상충지점은 분리시키며 교통류는 직각 교차·예각 합류가 원칙이다":"교통류는 직각 교차·예각 합류를 원칙으로 하고 상충면적은 좁게, 상충지점은 분리시킵니다.","상충면적을 넓히거나 우수 배수를 위한 것은 도류화 목적이 아니다":"상충면적을 넓히는 것이나 우수 배수는 도류화 목적에 들지 않습니다.","상충 이동류 감소, 용량 증대, 평균통행속도 증가가 장점이다":"상충 이동류가 줄고 용량이 커지며 평균통행속도가 오르는 것이 일방통행제의 장점입니다.","상충지점수가 적고 정지수를 줄여 교차로를 통과시킬 수 있다":"정지수를 줄여 교차로를 통과시킬 수 있고 상충지점수가 적은 도로가 일방통행도로입니다.","상충지점수를 충분히 늘리는 것은 목표가 아니다":"상충지점수를 충분히 늘리는 일은 목표에 들지 않습니다.","상호작용으로 영향을 받기 시작한다":"서비스수준 C는 다른 사용자와의 상호작용으로 영향을 받기 시작하는 상태입니다.","새 구조물 없이 접속 가능하나 원곡선 반지름 제약으로 속도가 저하된다":"루프연결로는 새 구조물 없이 접속할 수 있으나 원곡선 반지름 제약으로 속도가 떨어집니다.","새 링크 건설로 총 통행시간이 느는 Braess 역설이 있으며 균형이 사회적 총비용 최소화는 아니다":"균형이 사회적 총비용을 최소화하는 것은 아니며 새 링크 건설로 총 통행시간이 느는 Braess 역설이 있습니다.","생산비를 증가시키는 것은 교통의 기능이 아니다(생산성 향상·생산비 절감)":"생산성 향상과 생산비 절감이 교통의 기능이며 생산비를 증가시키는 것은 아닙니다.","생산적·자원절약적 국토이용체계 구축이 제3차 계획 목표다":"제3차 계획의 목표는 생산적·자원절약적 국토이용체계 구축입니다.","생활양식 변화추이, 산업입지 형태, 기술·가치관 변화가 정성적 예측변수다":"정성적 예측변수에는 생활양식 변화추이, 산업입지 형태, 기술·가치관 변화가 있습니다.","서비스수준은 Webster 공식에 포함되지 않는다":"Webster 공식에 서비스수준은 들어 있지 않습니다.","서비스 지향적인 것은 단기계획 특징이다":"서비스 지향적이라는 성격은 단기교통계획이 지닌 특징입니다.","서울특별시 도로원표는 서울특별시장이 관리한다":"서울특별시장이 서울특별시 도로원표를 관리합니다.","서울특별시 도로원표는 세종로광장 중앙에 있다":"세종로광장 중앙에 서울특별시 도로원표가 있습니다.","선박은 수상·수중 항행용 선박류이고 항공기는 항공법상 항공기를 뜻한다":"항공법상 항공기를 뜻하는 항공기와 달리 선박은 수상·수중 항행용 선박류를 가리킵니다.","선형불량 대책이 연석시설 개선인 것은 아니다":"선형불량 대책이 연석시설 개선이라는 설명은 틀립니다.","선형이론은 교통축, 다핵이론은 부도심과 연결되며 중심지이론은 시장원리가 아니다":"교통축과 연결되는 선형이론과 부도심과 연결되는 다핵이론과 달리 중심지이론은 시장원리가 아닙니다.","설계·건설단계에서 안전성을 평가해 위험요인을 찾는다":"위험요인을 찾으려고 설계·건설단계에서 안전성을 평가하는 것이 목적입니다.","설계속도, 감속차로 길이, 가속차로 길이를 고려하고 차로 수는 아니다":"차로 수는 고려사항이 아니고 설계속도, 감속차로 길이, 가속차로 길이를 고려합니다.","설계속도, 도로 형태, 버스 정차로 길이를 고려하고 차량 혼합율은 아니다":"차량 혼합율은 고려사항이 아니고 설계속도, 도로 형태, 버스 정차로 길이를 고려합니다.","설계속도 20km/h는 최소시거 25m, 30km/h는 40m, 40km/h는 60m다":"최소시거는 설계속도 20km/h에서 25m, 30km/h에서 40m, 40km/h에서 60m입니다.","설계속도 50km/h가 이상적이며 교통량 적은 쪽을 루프형으로 한다":"트럼펫형 루프연결로는 설계속도 50km/h가 이상적이며 교통량이 적은 쪽을 루프형으로 합니다.","설계속도 60km/h 미만은 3.0m다":"설계속도가 60km/h 미만이면 차로폭은 3.0m입니다.","설계속도 60km/h일 때 최소정지시거는 75m다":"최소정지시거는 설계속도 60km/h일 때 75m가 됩니다.","설계속도가 40km/h 이하인 경우에는 오르막차로를 설치하지 않을 수 있다":"40km/h 이하의 설계속도에서는 오르막차로를 설치하지 않을 수 있습니다.","설계용량은 통상 설계시간교통량보다 크다":"통상 설계시간교통량보다 설계용량이 더 큽니다.","설문조사, 히어링조사, 전화조사 결과는 1차 자료이고 통계연감은 2차 자료다":"히어링조사·설문조사·전화조사 결과는 1차 자료, 통계연감은 2차 자료입니다.","설치간격 300m 이상으로 연동효과가 없으면 중간에 신호등을 추가할 수 있다":"신호등 간격이 300m 이상이어서 연동효과가 없으면 사이에 신호등을 더 둘 수 있습니다.","설치목적을 충분히 달성하고 반응 시간 여유가 있는 곳에 설치하며 주의를 끌어야 한다":"반응 시간 여유가 있고 설치목적을 충분히 달성할 곳에 설치하며 주의를 끌어야 합니다.","설치의무 면제 신청서에는 시설물 위치·용도·규모, 신청인 정보, 부설주차장 규모를 적는다":"부설주차장 규모와 신청인 정보, 시설물 위치·용도·규모를 설치의무 면제 신청서에 적습니다.","성격·주의력·차량조작능력은 후천적 능력이고 현혹회복력은 아니다":"현혹회복력은 후천적 능력이 아니며 성격, 주의력, 차량조작능력이 후천적 능력입니다.","성장관리 정책은 도시 외연적 확산 방지, 자연환경 보존, 개발격차 시정이 목적이다":"도시 외연적 확산 방지와 자연환경 보존, 개발격차 시정을 성장관리 정책이 추구합니다.","성장척도이지 물리적 계획 요소가 아니다":"인구는 물리적 계획 요소가 아니라 성장척도입니다.","소공원·어린이공원·근린공원은 생활권공원이고 수변공원은 아니다":"수변공원은 생활권공원이 아니고 소공원, 어린이공원, 근린공원이 생활권공원입니다.","소방용 방화물통 5m 이내는 정차가 아니라 주차만 금지되는 장소다":"정차는 허용되고 주차만 금지되는 곳이 소방용 방화물통 5m 이내입니다.","소형자동차·대형자동차·세미트레일러는 설계기준차량이고 중장비는 아니다":"중장비는 설계기준차량이 아니며 소형자동차, 대형자동차, 세미트레일러가 설계기준차량입니다.","소화전·방화물통 흡수구 5m 이내, 터널 안·다리 위가 주차금지 장소다":"터널 안과 다리 위, 소화전·방화물통 흡수구 5m 이내에는 주차할 수 없습니다.","속도, 밀도, 교통량이 교통류 특성을 설명하는 3대 변수다":"교통류 특성을 설명하는 3대 변수는 속도, 밀도, 교통량입니다.","속도가 높은 곳, 사고건수가 많은 곳, 교통량이 많은 곳에 우선 설치한다":"교통량이 많은 곳, 사고건수가 많은 곳, 속도가 높은 곳에 먼저 설치합니다.","속도가 높을수록 치사율이 높고 커브지점은 정면충돌이 많다":"커브지점은 정면충돌이 많고 속도가 높을수록 치사율이 높습니다.","속도규제·단속, 추월금지구간 설정, 교통시설 설계에 지점속도 조사가 쓰인다":"지점속도 조사는 속도규제와 단속, 추월금지구간 설정, 교통시설 설계에 쓰입니다.","속도 높은 차량만 조사대상으로 삼는 것은 아니다":"조사대상을 속도 높은 차량만으로 삼는 것은 아닙니다.","속도제한, 이륜차 헬멧 착용, 면허 연령제한이 안전-이동성 상충의 예다":"안전과 이동성이 상충하는 예로 속도제한, 이륜차 헬멧 착용, 면허 연령제한이 있습니다.","속도조절, 불법회전 방지, 과대 도로포장 방지가 도류화 목적이다":"도류화 목적은 속도조절, 불법회전 방지, 과대 도로포장 방지입니다.","손실시간, 포화교통량, 접근로 교통량이 공식에 포함된다":"Webster 공식에는 손실시간, 포화교통량, 접근로 교통량이 포함됩니다.","수단선택이 아니라 통행분포 모형이다":"중력모형은 수단선택이 아니라 통행분포 모형입니다.","수요대응은 쉽지만 혼잡을 일으킨다":"버스는 수요 대응이 쉽지만 혼잡을 일으킵니다.","순편익의 크기가 고려되지 못하는 것이 단점이다":"순편익 크기를 고려하지 못하는 점이 단점입니다.","스키드마크 길이, 타이어-노면 마찰계수, 노면 종단경사로 제동 속도를 구한다":"제동 속도는 스키드마크 길이, 타이어-노면 마찰계수, 노면 종단경사로 구합니다.","승객당 도로공간이 작은 버스통행권은 버스전용차선이다":"버스전용차선은 승객당 도로공간이 작은 버스통행권입니다.","승객수요가 적은 지역엔 공영버스가 균형 공급에 유리하다":"공영버스는 승객수요가 적은 지역의 균형 공급에 유리합니다.","승객승차대가 낮아 승하차가 편리하고 예비지하철시스템도 경전철로 볼 수 있다":"예비지하철시스템도 경전철로 볼 수 있고, 승객승차대가 낮아 승하차가 편리합니다.","승객·화물 운송, 도시 연결, 이동성 부여가 교통의 기능이다":"교통의 기능은 승객·화물 운송, 도시 연결, 이동성 부여입니다.","승용·승합·화물자동차는 도로교통법상 자동차이고 자전거는 아니다":"자전거는 도로교통법상 자동차가 아니며 승용·승합·화물자동차가 자동차입니다.","승용자동차, 화물자동차, 특수자동차가 교통수단에 속한다":"교통수단에는 승용자동차, 화물자동차, 특수자동차가 속합니다.","승용자동차·대형자동차·세미트레일러가 기준이고 중형자동차는 아니다":"설계기준차량은 승용자동차, 대형자동차, 세미트레일러이고 중형자동차는 아닙니다.","승용차로만 구성된 교통류, 차로폭 3.5m 이상, 평지가 이상적 조건이다":"이상적 조건은 승용차로만 구성된 교통류, 차로폭 3.5m 이상, 평지입니다.","승용차부제, 혼잡통행료 부과, 자동차 운행제한도 시행 내용에 해당한다":"시행 내용에는 승용차부제, 혼잡통행료 부과, 자동차 운행제한도 들어갑니다.","승차 보유대수, 가구소득, CBD 거리로 설명되며 고용인구는 아니다":"가정기반통행은 승차 보유대수, 가구소득, CBD 거리로 설명되며 고용인구로는 설명하지 않습니다.","승차인원은 승차정원의 110% 이내, 화물 적재중량도 110% 이내다":"승차정원의 110% 이내로 태우고 화물도 110% 이내로 실어야 합니다.","승차인원조사는 감응루프 검지기로 얻을 수 없다":"감응루프 검지기로는 승차인원조사 결과를 얻을 수 없습니다.","시가화 상황·환경 판정 척도이며 인구·공공시설 균형 지표다":"밀도는 시가화 상황과 환경을 판정하는 척도이며 인구와 공공시설의 균형 지표입니다.","시간당 수송량은 지하철보다 작다":"시간당 수송량이 지하철보다 작은 편입니다.","시거는 차로중심선을 따라 측정한 거리다":"차로중심선을 따라 측정한 거리를 시거로 봅니다.","시공도에서는 차량 속도·위치·가속도를 알 수 있고 차량 종류는 알 수 없다":"차량 종류는 시공도에서 알 수 없고 차량 속도, 위치, 가속도는 알 수 있습니다.","시군구교통안전기본계획이 매년인 것은 아니다":"시군구교통안전기본계획을 매년 수립하는 것은 아닙니다.","시군구교통안전정책심의위원회는 지역 정책을 심의하며 위원장은 시도지사가 아니다":"위원장이 시도지사가 아니고 시군구교통안전정책심의위원회가 지역 정책을 심의합니다.","시·도경찰청장이 차로를 설치하며 보차 미분리 도로엔 길가장자리구역을 둔다":"보차 미분리 도로에는 길가장자리구역을 두고, 차로 설치는 시·도경찰청장이 합니다.","시도지사 등이 지정하는 교통혼잡도로는 대도시권 교통혼잡도로이며 5년 주기다":"5년 주기이며 시도지사 등이 지정하는 교통혼잡도로는 대도시권 교통혼잡도로입니다.","시동을 끄지 않고 잠시 떠난 상태도 정차의 정의가 아니다":"시동을 끈 채가 아니어도 잠시 떠난 상태는 정차의 정의로 보지 않습니다.","시선유도표지, 시선유도봉, 갈매기표지가 시선유도시설이고 도로반사경은 아니다":"도로반사경은 시선유도시설이 아니며 시선유도표지, 시선유도봉, 갈매기표지가 시선유도시설입니다.","시스템에 차량이 없을 확률은 1-교통강도(ρ)와 같다":"시스템에 차량이 없을 확률은 1에서 교통강도를 뺀 값과 같습니다.","시험차 주행법(Moving Survey)은 O-D 조사방법이 아니다":"O-D 조사방법 중에 시험차 주행법(Moving Survey)은 없습니다.","신호교차로를 한 번에 통과 못 하는 과도한 혼잡 상태다":"서비스수준 F는 신호교차로를 한 번에 통과하지 못하는 과도한 혼잡 상태입니다.","신호교차로보다 유지관리 부담이 적다":"유지관리 부담이 신호교차로보다 적은 편입니다.","신호등 색상 자체는 운영요소가 아니다":"신호등 색상 자체를 운영요소로 보지는 않습니다.","신호제어로 속도를 줄이거나 정지함에 따른 지체다":"신호제어 때문에 속도를 줄이거나 정지해서 생기는 지체가 제어지체입니다.","신호주기, 신호현시, 녹색시간이 신호등 운영요소다":"신호등의 운영요소는 신호주기, 신호현시, 녹색시간입니다.","신호주기 75초 교차로에서 조사간격법으로 정지지체를 계산":"신호주기가 75초인 교차로의 정지지체는 조사간격법으로 계산합니다.","실용교통용량은 결정 요인이 아니다":"황색신호를 결정하는 요인에 실용교통용량은 들지 않습니다.","안전개선의 시행 계획은 계획단계가 아닌 다음 단계다":"다음 단계에서 하는 일이 안전개선의 시행 계획이며 계획단계는 아닙니다.","안전설계지침 검토는 4단계에 포함되지 않는다":"안전설계지침 검토는 위험지점 분석 4단계에 포함되지 않습니다.","안전성, 편의성, 공공의 경제성이 공공이익 요소이고 신속성은 아니다":"신속성은 공공이익 요소가 아니며 안전성, 편의성, 공공의 경제성이 요소입니다.","안전한 도로설계, 사고다발지점 개선, 차량 안전설계는 공학 대책이다":"공학 대책에는 안전한 도로설계, 사고다발지점 개선, 차량 안전설계가 있습니다.","안정성이 우수하나 버스와 연계 불편이 있다":"지하철은 안정성이 우수하나 버스와 연계가 불편합니다.","앞지르기 당하는 차는 일정속도, 마주오는 차는 설계속도로 주행한다고 가정한다":"가정상 앞지르기를 당하는 차는 일정속도로, 마주오는 차는 설계속도로 달립니다.","앞지르기시거 측정 시 운전자 눈높이를 1.5m로 고정하는 것은 아니다":"운전자 눈높이를 1.5m로 고정해서 앞지르기시거를 재는 것은 아닙니다.","앞지르기 완료 후 반대편 차로 자동차와의 여유거리를 고려한다":"앞지르기를 마친 뒤 반대편 차로 자동차와의 여유거리를 고려합니다.","앞차와의 속도차, 반응민감도, 앞차와의 간격이 가속에 영향을 미친다":"앞차와의 간격이나 속도차, 반응민감도에 따라 가속하는 정도가 달라집니다.","야간 주행 안전성이 필요한 곳, 차로수·차로폭 변화구간, 선형 변화구간에 설치한다":"선형 변화구간과 차로수·차로폭 변화구간, 야간 주행 안전성이 필요한 곳에 설치합니다.","양방 보호좌회전은 마주보는 접근로가 동일 현시에 좌회전하는 신호이며 임계차로군은 최대 v/c를 갖는 차로군이다":"양방 보호좌회전은 마주보는 접근로가 같은 현시에 좌회전하는 신호입니다.","양호한 타이어가 마모된 타이어보다 마찰계수가 크다":"마모된 타이어보다 양호한 타이어의 마찰계수가 더 큽니다.","언제나 우회전·필요시 좌회전 가능은 적색신호의 뜻이 아니다":"언제나 우회전하거나 필요시 좌회전할 수 있다는 것은 적색신호의 뜻이 아닙니다.","엇갈림구간 설계속도는 영향 요소가 아니다":"엇갈림구간 설계속도는 교통류 특성에 영향을 미치는 요소가 아닙니다.","엇갈림구간의 길이, 형태, 차로수가 교통류 특성에 영향을 미치는 기하구조 요소다":"차로수와 길이, 형태는 엇갈림구간에서 교통류 특성에 영향을 미치는 기하구조 요소입니다.","엇갈림·굴절교차 변형교차는 피하고 교통특성이 다른 교통류는 분리한다":"교통특성이 다른 교통류는 분리하고 엇갈림이나 굴절교차 같은 변형교차는 피합니다.","에어백 같은 능동적 보호장비는 상충 예가 아니다":"에어백 같은 능동적 보호장비를 상충 예로 보지는 않습니다.","에티지오니는 혼합탐색, 디비도프는 주민집단 이익 옹호를 주장했다":"주민집단 이익 옹호는 디비도프가, 혼합탐색은 에티지오니가 주장했습니다.","역세권 개발사업은 100만㎡ 이상 기준이 아니다":"역세권 개발사업에는 100만㎡ 이상 기준이 적용되지 않습니다.","역세권에 주거기능을 배치하는 것은 입지배분 원칙이 아니다":"입지배분 원칙에 역세권 주거기능 배치는 들지 않습니다.","연간 사고건수, 사고율, 사고피해정도를 고려한다":"연간 사고건수, 사고율, 사고피해정도를 고려해 위험도지수를 구합니다.","연간총교통량을 365로 나눈 값이며 교통계획 기초자료로 쓴다":"교통계획 기초자료로 쓰는 AADT는 연간총교통량을 365로 나누어 구합니다.","연결로의 평면곡선부 최대 편경사는 8%이며 편경사는 높이변화 비율이 아니라 횡단경사다":"편경사는 높이변화 비율이 아니라 횡단경사이며 연결로 평면곡선부의 최대 편경사는 8%입니다.","연구목적·자료용도, 통계적 정확도, 연구범위 내 인구가 표본크기 결정 고려사항이다":"표본크기를 정할 때는 연구목적·자료용도, 통계적 정확도, 연구범위 내 인구를 고려합니다.","연동화가 쉽고 인력 교통량조사가 필요 없으며 단시간에 변동에 적응한다":"단시간의 변동에도 적응하는 감응신호는 연동화가 쉽고 인력 교통량조사가 필요 없습니다.","연료비, 운전기사 임금, 차량부품 구입비용이 가변비용이다":"가변비용은 연료비, 운전기사 임금, 차량부품 구입비용입니다.","연면적 1만㎡ 이상이나 높이제한 12m 이하는 해당 규정이 아니다":"연면적 1만㎡ 이상이나 높이제한 12m 이하는 이 규정에 해당하지 않습니다.","연속형은 20~90m 간격이며 굴곡부·곡선반경 작은 곳에 설치하는 것은 아니다":"굴곡부나 곡선반경이 작은 곳이 아니라 20~90m 간격으로 연속형을 설치합니다.","영문으로는 redevelopment, rehabilitation, conservation이다":"철거는 redevelopment, 수복은 rehabilitation, 보전은 conservation으로 영문 표기합니다.","예산 우선순위와 무관하게 소요예산을 책정하는 것은 목적이 아니다":"소요예산을 책정할 때 예산 우선순위를 무시하는 것은 목적이 될 수 없습니다.","예상서비스 수준이 설계서비스 수준보다 높을 때 설치하는 것은 아니다":"설계서비스 수준보다 예상서비스 수준이 높을 때 설치하는 것은 아닙니다.","오르막차로 설치, 미끄럼방지 포장은 시거불량 대책이 아니다":"시거불량 대책에 오르막차로 설치와 미끄럼방지 포장은 들지 않습니다.","오르막차로와 연결도로 주행속도는 검토사항이 아니다":"연결도로 주행속도와 오르막차로는 검토사항에 들지 않습니다.","오전 7시부터 오후 7시까지 하며 교차로 조사는 차종·방향별로 구분한다":"교차로 조사는 차종과 방향별로 나누며 오전 7시부터 오후 7시까지 조사합니다.","옵션존은 황색신호시간이 적정황색신호시간보다 클 때 생긴다":"적정황색신호시간보다 황색신호시간이 길 때 옵션존이 생깁니다.","완충구간·지주구간도 3요소에 포함되지 않는다":"완충구간과 지주구간도 노변방호책의 3요소에 포함되지 않습니다.","완충녹지·경관녹지·연결녹지는 기능별 녹지 종류다":"연결녹지, 경관녹지, 완충녹지가 기능별 녹지 종류입니다.","완충지대 포함 6개 동심원 구조로 본 것은 아니다":"동심원 구조를 완충지대 포함 6개로 보는 견해는 아닙니다.","요금소가 4개로 분산돼 관리비가 늘고 평면교차부 용량이 작아진다":"요금소가 4개로 분산되어 관리비가 늘고 평면교차부 용량이 작아지는 것이 단점입니다.","용도지역 지정, 기반시설 정비, 지구단위계획은 포함되나 도시기본계획 지정은 아니다":"도시관리계획에 들어가는 것은 용도지역 지정, 기반시설 정비, 지구단위계획이며 도시기본계획 지정은 빠집니다.","용량분석 대상 도로는 접근기능보다 이동기능이 큰 도로이다":"접근기능보다 이동기능이 큰 도로가 용량분석 대상입니다.","용지가 많이 드는 것은 다이아몬드형의 단점이 아니다":"다이아몬드형의 단점에 용지가 많이 드는 점은 들지 않습니다.","우회거리가 짧고 용지가 적게 들며 저급도로 교차에 적합하다":"저급도로 교차에 적합하고 우회거리가 짧으며 용지가 적게 듭니다.","우회전 시 미리 우측가장자리로 서행하고 좌회전 시 중앙선 따라 교차로 중심 안쪽을 서행한다":"우회전할 때는 미리 우측가장자리에서 서행하고, 좌회전할 때는 중앙선을 따라 교차로 중심 안쪽에서 서행합니다.","운전자가 핸들조작에 곤란을 느끼지 않도록 하고 4~6초 주행 가능한 길이를 확보한다":"4~6초 주행 가능한 길이를 확보하여 운전자가 핸들조작에 곤란을 느끼지 않게 합니다.","운전자 교육 참여자는 사고율이 낮고 10대 운전자는 사고율이 높다":"10대 운전자의 사고율은 높고 운전자 교육에 참여한 사람의 사고율은 낮습니다.","운전자의 시각·심리적 측면에서 양호하고 주위 경관과 조화를 이뤄야 한다":"주위 경관과 조화를 이루고 운전자의 시각·심리적 측면에서 양호해야 합니다.","운전자의 주의를 끌어서는 안 된다는 것은 요구조건이 아니다(주의를 끌어야 함)":"주의를 끌어서는 안 된다는 것은 요구조건이 아니고 오히려 주의를 끌어야 합니다.","운전자 주의를 끌고 적절한 반응시간을 확보할 위치에 설치하며 법적 근거가 있어야 한다":"법적 근거가 있어야 하고 운전자 주의를 끌며 적절한 반응시간을 확보할 위치에 설치합니다.","원단위법·P요소법·누적주차수요법은 주차수요 추정법이고 프라타모델법은 아니다":"프라타모델법은 주차수요 추정법이 아니며 원단위법, P요소법, 누적주차수요법이 추정법입니다.","원동기장치자전거만 다니는 도로를 뜻하는 것도 아니다":"원동기장치자전거만 다닐 수 있는 도로라는 뜻도 아닙니다.","원형이론·중심지이론은 도시내부구조이론에 포함되지 않는다":"도시내부구조이론에는 원형이론과 중심지이론이 들어가지 않습니다.","원활한 감속, 대기공간 확보, 직진차량 영향 최소화 기능을 한다":"직진차량에 주는 영향을 최소화하고 감속을 원활하게 하며 대기공간을 확보하는 것이 기능입니다.","월별 개선사업 계획은 포함 내용이 아니다":"개선사업계획에 월별 개선사업 계획은 들어가지 않습니다.","위로부터 적색, 황색, 녹색 순으로 배열한다":"삼색등화는 위로부터 적색, 황색, 녹색 순으로 배열합니다.","위빙 거리, 대기차량 길이, 설계속도가 교차로 간격 결정 고려사항이다":"교차로 간격은 위빙 거리와 대기차량 길이, 설계속도를 고려해 정합니다.","위원장·부위원장 포함 30명 이내이며 공무원 아닌 위원 임기는 2년이다":"중앙위원회는 위원장과 부위원장을 포함해 30명 이내이며 공무원이 아닌 위원의 임기는 2년입니다.","위원장이 건설교통부장관인 것은 아니다":"건설교통부장관이 위원장이라는 설명은 틀립니다.","위원회가 30인 이내로 고정된 것도 아니다":"30인 이내로 위원회 인원이 고정된 것도 아닙니다.","위원회의 조직·기능·운영에 관한 사항은 대통령령으로 정한다":"조직·기능·운영에 관한 위원회 사항은 대통령령으로 정합니다.","위해요소에 대한 적절한 행동을 결정하는 과정이다":"위해요소에 대해 적절한 행동을 결정하는 과정을 행동판단이라 합니다.","위험한 흐름을 제어하고 관제시설 공간을 확보하되 설치횟수는 최소화한다":"설치횟수는 최소화하면서 위험한 흐름을 제어하고 관제시설 공간을 확보합니다.","유료도로 지정에 관한 사항은 심의사항이 아니다":"심의사항에 유료도로 지정에 관한 사항은 들지 않습니다.","유사 특성 장소의 평균사고율로 위험구간을 선정하며 실제사고율이 낮으면 위험구간이 아니다":"실제사고율이 낮으면 위험구간이 아니며 유사 특성 장소의 평균사고율로 선정합니다.","유원지 규모는 1만㎡ 이상이며 초등학교 통학거리가 1500m 이내인 것은 아니다":"초등학교 통학거리가 1500m 이내인 것은 아니며 유원지 규모는 1만㎡ 이상입니다.","유지관리비용과 수익에 관한 사항은 포함되지 않는다":"유지관리비용과 수익에 관한 사항은 포함 대상이 아닙니다.","유턴 시 도움을 주는 것은 중앙분리대의 기능이 아니다":"중앙분리대의 기능에 유턴 시 도움은 들지 않습니다.","유효녹색시간은 녹색시간+황색시간-(출발손실시간+소거손실시간)이다":"유효녹색시간은 녹색시간에 황색시간을 더하고 출발손실시간과 소거손실시간의 합을 뺀 값입니다.","응모추출법은 비확률(유의)추출법에 해당한다":"응모추출법은 비확률추출법, 곧 유의추출법에 해당합니다.","의료시설(정신병원 등 제외)·판매영업시설·방송국도 150㎡당 1대다":"150㎡마다 1대를 두는 대상에는 의료시설(정신병원 등 제외), 판매영업시설, 방송국도 들어갑니다.","의사결정과정 민감도분석의 원리는 AHP 3대 원리가 아니다":"AHP 3대 원리에 의사결정과정 민감도분석의 원리는 들지 않습니다.","이동성보다 접근성이 큰 도로다":"집산도로는 이동성보다 접근성이 큰 도로입니다.","이미 진입한 차에 진로를 양보한다":"교통정리 없는 교차로에서는 이미 진입한 차에 진로를 양보합니다.","이상적 조건에서 차로당 승용차의 시간당 최대 교통량이다":"기본 교통용량은 이상적 조건에서 한 차로를 지나는 승용차의 시간당 최대 교통량입니다.","이주대책비는 국가지원지방도 건설·유지관리비에 포함된다":"국가지원지방도 건설·유지관리비에는 이주대책비도 들어갑니다.","인구는 32,000~58,000명이며 토지는 영구히 공유화한다":"토지를 영구히 공유화하고 인구는 32,000~58,000명으로 정한 것이 전원도시입니다.","인구성장이 완만→급증→감소의 S자형이면 로지스틱곡선법을 쓴다":"로지스틱곡선법은 인구성장이 완만하다가 급증하고 줄어드는 S자형일 때 씁니다.","인구 집중, 도시적 산업 확산, 고밀·고층화로 나타난다":"인구 집중과 도시적 산업의 확산, 고밀·고층화가 도시화의 모습입니다.","인근주민 5명 이상 동의서는 첨부서류가 아니다":"첨부서류에 인근주민 5명 이상 동의서는 들지 않습니다.","인접 설계구간과 설계속도 차이는 30km/h 이하가 기준이 아니라 더 작은 값이 기준이다":"인접 설계구간과의 설계속도 차이 기준은 30km/h 이하가 아니라 그보다 작은 값입니다.","인접지역 개발이 많을수록 K30이 증가하는 것은 아니다":"인접지역 개발이 많을수록 K30이 커진다고 볼 수는 없습니다.","인종별·집단별 구분이나 문화적 차이에 따른 주거 배치를 특징으로 보지는 않는다":"주거 배치가 인종별·집단별 구분이나 문화적 차이에 따른다고 보지는 않습니다.","일반 교차로보다 상충지점수가 적고 원형 교통섬을 우회해 통과한다":"원형 교통섬을 우회해 통과하며 일반 교차로보다 상충지점수가 적습니다.","일반도로 설계속도 60kph 미만 지방지역은 3.0m 이상이고 고속도로 도시지역 3.0m는 아니다":"고속도로 도시지역 3.0m는 해당하지 않고, 설계속도 60kph 미만 일반도로 지방지역이 3.0m 이상입니다.","일반도로에서는 1.3배가 확대 기준이다":"1.3배는 일반도로에서의 확대 기준입니다.","일반도로 주간선도로급은 국도이며 지방도가 집산도로 기능만 하는 것은 아니다":"지방도가 집산도로 기능만 하는 것은 아니며 일반도로 주간선도로급이 국도입니다.","일방통행, 도로파손으로 우측통행 불가, 우측 폭 6m 미만에서 앞지르기 시가 예외 사유다":"앞지르기 때 우측 폭이 6m 미만이거나 일방통행, 도로파손으로 우측통행이 불가하면 예외 사유입니다.","일방통행제 실시 초기엔 사고율이 증가하는 경우가 있다":"사고율이 증가하는 경우가 일방통행제 실시 초기에 있습니다.","일방향정지 교차로는 비신호교차로 종류에 포함되지 않는다":"비신호교차로 종류에 일방향정지 교차로는 넣지 않습니다.","일정거리 이상 보행·교통수단으로 이동하는 사람이다":"통행자는 일정거리 이상을 걷거나 교통수단으로 이동하는 사람입니다.","입출고자 통로 너비는 50cm보다 커야 하며 50cm 이상만으로는 부족하다":"입출고자 통로 너비를 50cm 이상으로만 하면 부족하고 50cm보다 커야 합니다.","자극을 이해하는 과정으로 물체뿐 아니라 속도까지 포함한다":"물체뿐 아니라 속도까지 포함해 자극을 이해하는 과정이 식별입니다.","자동차 교통량은 결정요소가 아니다":"횡단시간을 결정하는 요소에 자동차 교통량은 들지 않습니다.","자동차는 쿨데삭 도로로 이용되고 중앙에 대공원을 둔다":"중앙에 대공원을 두고 쿨데삭 도로로 자동차를 이용하게 합니다.","자동차만 다닐 수 있는 도로다":"자동차만 통행할 수 있도록 정한 도로가 자동차전용도로입니다.","자동차·보행자 분리도로망, 도시성 향상, 인구구성 다양화를 지향한다":"인구구성 다양화와 도시성 향상, 자동차·보행자 분리도로망을 지향하는 신도시입니다.","자동차 생산시설현황은 기초조사 사항이 아니다":"기초조사 사항에 자동차 생산시설현황은 들지 않습니다.","자동차 외 방법으로 통행·출입할 수 없으며 관리청이 금지 대상을 명시한다":"자동차 외 방법으로 통행·출입할 수 없고 금지 대상은 관리청이 명시합니다.","자동차의 고속 운행에만 사용하도록 지정된 도로다":"고속 운행에만 사용하도록 자동차에 지정된 도로입니다.","자동차전용도로 지역 내 통행에는 측도나 접근로가 필요하다":"측도나 접근로가 있어야 자동차전용도로 지역 내 통행이 가능합니다.","자본집약적이고 장기적 관점이며 여러 수단을 동시 고려하지 않는다":"장기교통계획은 여러 수단을 동시에 고려하지 않으며 자본집약적이고 장기적 관점에서 짜입니다.","자연(nature)은 린치의 형성요소가 아니다":"린치가 든 형성요소에 자연(nature)은 없습니다.","자전거·보행자 분리 기준은 자전거교통량 80대/시(약 700대/일)다":"자전거교통량 80대/시(약 700대/일)가 자전거·보행자 분리 기준입니다.","자전거전용도로, 자전거·보행자겸용도로, 자전거·자동차겸용도로로 구분한다":"자전거 도로를 구분하면 자전거전용도로, 자전거·보행자겸용도로, 자전거·자동차겸용도로 세 가지입니다.","잠재가격(SP)은 그 경제성 평가 지표에 포함되지 않는다":"경제성 평가 지표 중 잠재가격(SP)은 포함되지 않는 항목입니다.","장기교통계획의 일부분인 것은 TSM 특징이 아니다(단기적)":"장기교통계획의 일부분인 것은 TSM 특징이 아니고 TSM은 단기적입니다.","장래 교통수요예측, 진출입동선 개선대책, 대중교통 개선대책이 평가 내용이다":"평가 내용으로 다루는 것은 장래 교통수요예측과 진출입동선 개선대책, 대중교통 개선대책입니다.","장소·시간 변화를 비교분석해 국가 안전정책 기초자료로 쓴다":"국가 안전정책 기초자료로 쓰려고 장소·시간 변화를 비교분석합니다.","장애물 제거, 예고표지 설치, 시선유도표지 설치가 시거불량 대책이다":"시거불량 대책에는 장애물 제거, 예고표지 설치, 시선유도표지 설치가 있습니다.","재개발·재건축·주거환경개선사업이 정비사업 종류이고 주택건설사업은 아니다":"주택건설사업은 정비사업 종류가 아니며 재개발, 재건축, 주거환경개선사업이 종류입니다.","재난 시 매설 기반시설 피해를 최소화하며 지지력에 손상을 입히는 것은 아니다":"매설 기반시설 피해를 재난 시 최소화하며 지지력에 손상을 입히지는 않습니다.","재원 조달방안, 총투자 규모, 시행주체가 개선사업계획 포함 내용이다":"개선사업계획에는 재원 조달방안, 총투자 규모, 시행주체가 들어갑니다.","재택근무는 노출통제 전략이고 운전자교육·가로조명 증설은 아니다":"운전자교육과 가로조명 증설이 아니라 재택근무가 노출통제 전략입니다.","저렴한 비용, 빠른 효과측정, 기존시설 최대이용이 TSM 특징이다":"TSM의 특징은 저렴한 비용, 빠른 효과측정, 기존시설 최대이용입니다.","저속차량, 정지, 출발이 충격파를 일으키고 추월은 아니다":"추월은 충격파 원인이 아니며 저속차량, 정지, 출발이 충격파를 일으킵니다.","저투자·단기편익·기존시설 효율적 이용이 특징이며 시설지향적이지 않다":"시설지향적이지 않은 TSM은 저투자와 단기편익, 기존시설의 효율적 이용을 특징으로 합니다.","적색등화에서도 직진 측면교통을 방해하지 않으면 우회전할 수 있다":"직진 측면교통을 방해하지 않는다면 적색등화에서도 우회전이 가능합니다.","적절한 반응을 위해 충분한 시간이 확보되는 곳에 설치해야 한다":"충분한 시간이 확보되는 곳에 설치해야 적절히 반응할 수 있습니다.","전달은 PIEV 과정에 속하지 않는다":"전달은 PIEV 과정에 들지 않습니다.","전량배분법·용량제약법·다경로배분법은 통행배분 기법이고 카테고리분석법은 아니다":"카테고리분석법은 통행배분 기법이 아니며 전량배분법, 용량제약법, 다경로배분법이 통행배분 기법입니다.","전용주거지역, 유통상업지역, 준공업지역은 용도지역이고 개발제한지역은 아니다":"개발제한지역은 용도지역이 아니며 전용주거지역, 유통상업지역, 준공업지역이 용도지역입니다.","점검단 구성·운영에 관한 사항을 자치단체장이 정하는 것은 아니다":"자치단체장이 점검단 구성·운영에 관한 사항을 정하는 것은 아닙니다.","점검단장은 참여 전문가 중 국토교통부장관이 위촉한다":"참여 전문가 중에서 점검단장을 위촉하는 사람은 국토교통부장관입니다.","점·선·면으로 되어 있고 속성자료가 3차원 화상인 것은 아니다":"속성자료가 3차원 화상인 것은 아니며 도형자료는 점·선·면으로 되어 있습니다.","점유율, 속도, 교통량을 조사할 수 있다":"감응루프 검지기로 점유율, 속도, 교통량을 조사할 수 있습니다.","점 자료의 공간분석 내용이 아니다":"네트워크 분석은 점 자료의 공간분석 내용이 아닙니다.","점진적 계획, 급진적 계획, 옹호적 계획이 허드슨의 분류에 해당한다":"허드슨의 분류에는 점진적 계획, 급진적 계획, 옹호적 계획이 있습니다.","접근로 교통량, 횡단보도 길이, 보행자 속도를 고려한다":"녹색시간은 접근로 교통량, 횡단보도 길이, 보행자 속도를 고려해 설계합니다.","접근부 정지선 상류 75m 이내 주정차 없고 60m 이내 진출입 차량 없음이 조건이다":"정지선 상류 75m 이내에 주정차가 없고 60m 이내에 진출입 차량이 없어야 하는 접근부 조건입니다.","접속경사는 15% 이상이 아니라 그보다 완만해야 한다":"15% 이상이 아니라 그보다 완만한 접속경사여야 합니다.","정당한 사유 없는 미납 주차, 지정구획 외 주차, 목적 외 이용이 제한 대상이다":"지정구획 외 주차, 목적 외 이용, 정당한 사유 없는 미납 주차가 제한 대상입니다.","정류장 시설 설치비용은 가변비용이 아니라 고정비다":"가변비용이 아니라 고정비에 들어가는 것이 정류장 시설 설치비용입니다.","정보표지는 경찰청 분류의 교통안전표지가 아니다":"경찰청 분류의 교통안전표지에 정보표지는 들지 않습니다.","정부조직법상 중앙행정기관 중 대통령령으로 정한 기관이다":"대통령령이 정한 기관이 정부조직법상 중앙행정기관 중 지정행정기관입니다.","정비기반시설은 양호하나 건축물이 노후·불량한 지역 개선사업이다":"노후·불량한 건축물이 있으나 정비기반시설은 양호한 지역을 개선하는 사업입니다.","정지·미끄럼 흔적, 편주 흔적, 최종 위치가 재현 자료이고 차량 검사 유무는 아니다":"차량 검사 유무는 재현 자료가 아니며 정지·미끄럼 흔적, 편주 흔적, 최종 위치가 재현 자료입니다.","정지선 위치를 후진시키는 것은 교통섬의 효과가 아니다":"교통섬의 효과에 정지선 위치를 후진시키는 것은 들지 않습니다.","정지시거는 설계속도와 관련 있고 추월시거도 설계속도와 무관하지 않다":"정지시거뿐 아니라 추월시거도 설계속도와 무관하지 않습니다.","정지지체, 가속지체, 감속지체가 접근지체에 포함된다":"접근지체에는 정지지체, 가속지체, 감속지체가 포함됩니다.","정차는 5분을 초과하지 않고 정지하는 주차 외의 정지상태다":"주차 외의 정지상태로 5분을 넘지 않는 것이 정차입니다.","정차는 5분 초과하지 않고 차를 세우는 것이며 서행은 즉시 정지 가능한 느린 속도다":"정차는 5분을 넘지 않게 차를 세우는 것이고 서행은 즉시 정지할 수 있는 느린 속도입니다.","제시된 타당한 의견은 도시기본계획에 반영해야 한다":"도시기본계획에는 공청회에서 제시된 타당한 의견을 반영해야 합니다.","제한속도가 너무 높거나 낮으면 무시되므로 적절히 설정해야 한다":"제한속도가 지나치게 높거나 낮으면 무시되기 때문에 적절한 설정이 필요합니다.","조건이 비슷한 도시의 인구성장과정을 적용하며 비교도시는 계획도시보다 작지 않아야 한다":"비교도시는 계획도시보다 작지 않아야 하며 조건이 비슷한 도시의 인구성장과정을 적용합니다.","조명도가 낮은 곳은 우선 설치 기준이 아니다":"조명도가 낮은 곳은 먼저 설치할 기준에 들지 않습니다.","조사·연구를 수행하며 위원장·부위원장은 건설교통부장관이 임명한다":"중앙도시계획위원회는 조사·연구를 수행하며 위원장과 부위원장은 건설교통부장관이 임명합니다.","존간 통행비용을 고려하지 않고 존의 성장률을 적용한다":"존의 성장률을 적용하며 존간 통행비용은 고려하지 않는 방법입니다.","존 경계는 행정구역과 일치시키고 지형적 경계를 존 경계로 삼는다":"존의 경계는 행정구역과 맞추고 지형적 경계도 존 경계로 삼습니다.","존 내부 통행은 적고 사회경제적 특성은 균일해야 하며 존 모양이 직사각형일 필요는 없다":"존 모양이 직사각형일 필요는 없으며 존 내부 통행은 적고 사회경제적 특성은 균일해야 합니다.","종사원 교통안전 교육은 진단 후 조치가 아니다":"진단 후 조치에 종사원 교통안전 교육은 들지 않습니다.","좌측도로 차가 우선 양보받는 것은 아니다(우측 차가 우선)":"우선순위가 같으면 좌측도로 차가 아니라 우측 차가 우선입니다.","좌측부분 폭이 부족한 것은 예외 사유가 아니다":"좌측부분의 폭이 부족해도 그것이 예외 사유가 되지는 않습니다.","좌회전 보행자 유무는 조사 항목이 아니다":"조사 항목에 좌회전 보행자 유무는 들어가지 않습니다.","좌회전신호 유무, 좌회전차로 유무, 좌회전 교통량을 조사해야 한다":"조사해야 할 항목은 좌회전 교통량과 좌회전신호 유무, 좌회전차로 유무입니다.","좌회전전용차로, 입체분리시설, 신호기 설치는 교차로 사고방지대책이다":"교차로 사고방지대책에는 좌회전전용차로, 입체분리시설, 신호기 설치가 있습니다.","좌회전 전용차로 교차로는 주기가 길어지면 대기행렬이 변하며 주기가 정지지체에 영향을 준다":"주기가 정지지체에 영향을 주며 길어지면 좌회전 전용차로 교차로의 대기행렬이 변합니다.","주간선도로는 일반국도·특별시도·광역시도이고 보조간선도로가 지방도·군도·시도인 것은 아니다":"보조간선도로가 지방도·군도·시도라는 설명은 틀리고 주간선도로가 일반국도·특별시도·광역시도입니다.","주간선도로 도시지역 80km/h, 보조간선도로 지방 평지 70km/h, 국지도로 지방 평지 50km/h다":"도시지역 주간선도로 80km/h, 지방 평지 보조간선도로 70km/h, 지방 평지 국지도로 50km/h가 기준값입니다.","주간선도로변에 상업기능을 배치하고 토지이용·교통 관계를 고려해 입지를 정한다":"입지는 토지이용과 교통 관계를 고려해 정하며 상업기능은 주간선도로변에 둡니다.","주간선도로와 교차하면 입체교차시설을 설치하고 보행자우선구조로 한다":"주간선도로와 교차할 때는 보행자우선구조로 하고 입체교차시설을 설치합니다.","주거구는 슈퍼블록 단위로 계획한다":"슈퍼블록 단위로 주거구를 계획합니다.","주거단지 대규모화, 안전성·쾌적성 확보, 외부생활공간 체계화가 필요성의 원인이다":"외부생활공간 체계화와 안전성·쾌적성 확보, 주거단지 대규모화가 필요성의 원인입니다.","주거지 내 통과교통을 허용하지 않으며 도로를 목적별로 분리한다":"도로를 목적별로 분리하며 주거지 내 통과교통은 허용하지 않습니다.","주구는 초등학교 1개교분 인구를 가지며 통과교통은 우회시킨다":"통과교통은 우회시키며 주구는 초등학교 1개교분 인구를 갖습니다.","주구별 요구에 맞는 소공원·레크레이션 공간을 가진다":"소공원과 레크레이션 공간을 주구별 요구에 맞게 두어야 합니다.","주기길이, 현시순서, 현시분할이 신호시간계획으로 결정되는 변수다":"신호시간계획으로 정하는 변수에는 주기길이, 현시순서, 현시분할이 있습니다.","주도로 통행량이 8시간 기준 시간당 600대 이상이면 신호등 설치기준에 해당한다":"8시간 기준 시간당 600대 이상의 주도로 통행량이 신호등 설치기준에 해당합니다.","주민은 기반시설 설치 등에 관해 도시관리계획 입안을 제안할 수 있다":"기반시설 설치 등에 관해 도시관리계획 입안을 제안하는 일은 주민이 할 수 있습니다.","주민은 도시계획 입안·집행에 직간접 참여할 수 있다":"도시계획 입안과 집행에 주민이 직간접으로 참여할 수 있습니다.","주민참여가 개발이익을 균등 배분하기 위한 것은 아니다":"개발이익을 균등 배분하려고 주민참여를 하는 것은 아닙니다.","주변 주민에게 재화·용역을 공급하는 정주공간이다":"중심지는 주변 주민에게 재화와 용역을 공급하는 정주공간입니다.","주요 지하매설물 안전대책도 심의사항이 아니다":"심의사항에 주요 지하매설물 안전대책도 들지 않습니다.","주의·규제·지시 내용을 노면에 기호·문자로 나타낸다":"노면에 기호와 문자로 주의·규제·지시 내용을 나타냅니다.","주의표지, 규제표지, 지시표지가 교통안전표지 종류이고 이정표지는 아니다":"이정표지는 교통안전표지 종류가 아니며 주의표지, 규제표지, 지시표지가 종류입니다.","주의표지, 보조표지, 지시표지가 안전표지 종류이고 위험표지는 아니다":"위험표지는 안전표지 종류가 아니며 주의표지, 보조표지, 지시표지가 종류입니다.","주의표지 설치, 가로조명시설 증설, 네온사인 제한이 야간사고 개선대책이다":"야간사고 개선대책에는 주의표지 설치, 가로조명시설 증설, 네온사인 제한이 있습니다.","주차구획은 너비 2.3m 이상, 운반기 바닥너비는 1.85m 이상이다":"운반기 바닥너비는 1.85m 이상으로, 주차구획 너비는 2.3m 이상으로 합니다.","주차금지표지는 청색바탕 백색문자이고 일방통행표지는 청색바탕 백색기호다":"일방통행표지는 청색바탕 백색기호이고, 주차금지표지는 청색바탕 백색문자입니다.","주차시설 조사·분석, 주차수요예측·공급계획, 주차관리정책 방향이 주차계획에 포함된다":"주차계획에는 주차시설 조사·분석, 주차수요예측·공급계획, 주차관리정책 방향이 들어갑니다.","주차장법 목적은 자동차교통 원활, 공중 편의도모, 도시기능 유지·증진이고 정부 재원확보는 아니다":"주차장법은 정부 재원확보가 아니라 자동차교통 원활, 공중 편의도모, 도시기능 유지·증진을 목적으로 합니다.","주차장·삭도·운하는 교통시설이고 광장은 공간시설이다":"광장은 공간시설이고 주차장, 삭도, 운하가 교통시설입니다.","주차제한구역 확대, 버스전용차로, 자동차 통행제한구역은 수요 억제 방법이다":"수요 억제 방법에는 주차제한구역 확대, 버스전용차로, 자동차 통행제한구역이 있습니다.","주택부족·교통난·환경파괴가 우리나라 대도시의 문제다":"우리나라 대도시의 문제로는 주택부족, 교통난, 환경파괴를 듭니다.","주행속도가 크다고 곡선반경이나 편경사가 작아도 되는 것은 아니다":"주행속도가 크면 곡선반경이나 편경사를 작게 해도 된다는 뜻은 아닙니다.","중량이 작을수록, 속도가 증가해도 작아지지 않는다":"회전저항은 중량이 작을수록 작아지며 속도가 증가한다고 작아지지는 않습니다.","중력모형·프라타모형·간섭기회모형은 통행분포 모형이고 회귀분석법은 아니다":"회귀분석법은 통행분포 모형이 아니며 중력모형, 프라타모형, 간섭기회모형이 통행분포 모형입니다.","중로1류는 15~20m가 아니고 대로3류는 20~25m가 아니다":"15~20m는 중로1류가 아니고, 20~25m도 대로3류가 아닙니다.","중소도시는 철도역 부근에 설치해 승강에 이점을 준다":"승강에 이점을 주려고 중소도시 터미널은 철도역 부근에 설치합니다.","중심도시·교통권역 지정은 업무범위가 아니다":"중심도시와 교통권역 지정은 지방위원회의 업무범위가 아닙니다.","중심도시로부터 지리적으로 분리되고 경제적으로 연결된 독립도시다":"지리적으로는 중심도시와 분리되고 경제적으로는 연결된 독립도시가 위성도시입니다.","중심상업·근린상업·유통상업지역은 상업지역 세분이고 준상업지역은 아니다":"준상업지역은 세분 항목이 아니며 중심상업, 근린상업, 유통상업지역이 세분입니다.","중심성은 중심기능의 다양성으로 표현되며 교통비가 도달범위를 결정한다":"교통비가 도달범위를 결정하며 중심성은 중심기능의 다양성으로 표현됩니다.","중심지 기점으로 간선도로 따라 도시개발축을 형성한다":"간선도로를 따라 중심지에서 도시개발축이 형성되는 도시 형태가 방사형입니다.","중심지역은 중심상업·업무기능의 최상위 중심지이며 최외곽은 통근자지대다":"최외곽은 통근자지대이고 중심지역은 중심상업·업무기능의 최상위 중심지입니다.","중심지이론이 1차·2차 산업 입지론인 것은 아니다":"1차·2차 산업 입지론이 중심지이론인 것은 아닙니다.","중앙분리대로 줄이는 사고유형이 아니다":"중앙분리대로 줄일 수 있는 사고유형에 단독사고는 들지 않습니다.","중앙분리대 측대 폭은 설계속도 80km/h 이상이면 더 넓게 한다":"설계속도 80km/h 이상이면 중앙분리대 측대 폭을 더 넓게 합니다.","중장기 정책방향, 교통문화 향상목표, 부문별 사고 발생현황 분석을 포함하며 대중교통체계 개선은 아니다":"대중교통체계 개선은 제외되고, 중장기 정책방향, 교통문화 향상목표, 부문별 사고 발생현황 분석이 들어갑니다.","지각·식별·판단·반응이 PIEV 과정이다":"PIEV 과정은 지각, 식별, 판단, 반응입니다.","지구단위계획 수립지역, 조례로 정한 지역, 산림사업 지역은 위원회 심의를 거치지 않을 수 있다":"산림사업 지역과 조례로 정한 지역, 지구단위계획 수립지역은 위원회 심의를 거치지 않을 수 있습니다.","지방경찰청장과 경찰서장은 위험방지를 위해 통행을 금지·제한할 수 있다":"위험방지를 위해 통행을 금지하거나 제한하는 권한이 지방경찰청장과 경찰서장에게 있습니다.","지방경찰청장이 횡단보도표시·표지판을 설치한다":"횡단보도표시와 표지판의 설치는 지방경찰청장이 맡습니다.","지방지역 도로가 도시 내 도로보다 K계수가 높다":"도시 내 도로보다 지방지역 도로의 K계수가 더 높습니다.","지식경제부, 농림수산식품부, 교육과학기술부가 지정행정기관이고 국방부는 아니다":"국방부는 지정행정기관이 아니고 지식경제부, 농림수산식품부, 교육과학기술부가 지정행정기관입니다.","지역교통계획, 도시교통계획, 지구교통계획이 공간적 범위 분류이고 간선도로계획은 아니다":"간선도로계획은 공간적 범위 분류가 아니며 지역·도시·지구교통계획이 분류입니다.","지역교통안전시행계획은 매년, 국가·시도교통안전기본계획은 5년 단위로 수립한다":"국가·시도교통안전기본계획은 5년 단위, 지역교통안전시행계획은 매년 수립합니다.","지점은 제한돼 있어 전국 모든 구간을 대표할 수 없다":"상시조사는 지점이 제한돼 있어 전국 모든 구간을 대표할 수 없습니다.","지체는 여러 요인의 복합변수이며 주기 길이는 그중 하나다":"주기 길이는 지체를 만드는 여러 요인 가운데 하나입니다.","지하식은 날씨로부터 보호되나 도시미관을 해치지 않는 것은 아니다":"도시미관을 해치지 않는 것은 아니며 지하식은 날씨로부터 보호됩니다.","지형을 무시하는 경향이 있고 명백한 동선체계이며 정방형·삼각형 패턴이 있다":"지형을 무시하는 경향이 있으나 동선체계가 명백하고 정방형과 삼각형 패턴이 있습니다.","지형이 평탄한 도시에 적합하고 도로기능 다양성이 결여되기 쉽다":"도로기능의 다양성이 결여되기 쉬운 이 형식은 지형이 평탄한 도시에 적합합니다.","직각충돌사고, 정면충돌사고, 보행자사고를 줄이는 효과가 있다":"보행자사고와 직각충돌사고, 정면충돌사고를 줄이는 효과가 중앙분리대에 있습니다.","직선모형은 직선성 가정이 실제 자료와 안 맞을 수 있다":"Greenshields 직선모형은 직선성 가정이 실제 자료와 맞지 않을 수 있습니다.","직선형·지수형·종형이 있고 포물선형은 아니다":"속도-밀도 모형은 직선형, 지수형, 종형이 있고 포물선형은 아닙니다.","직접수요모형은 발생·목적지·수단·노선을 단일식으로 동시에 예측한다":"발생, 목적지, 수단, 노선을 한 식으로 동시에 예측하는 것이 직접수요모형입니다.","직진차로에서 좌회전차로로 교통류를 유도하며 급격한 변경·감속을 막는다":"급격한 변경과 감속을 막으려고 직진차로에서 좌회전차로로 교통류를 유도하는 것이 차로 테이퍼입니다.","직진차로와 분리해 우회전·좌회전·유턴을 돕는 차로다":"회전차로는 직진차로와 분리해 우회전, 좌회전, 유턴을 돕는 차로입니다.","진입·진출을 원활히 유도하는 노면표시를 설치한다":"노면표시를 설치해 진입과 진출을 원활하게 유도합니다.","진입차량이 회전차량보다 우선권을 갖는 것은 아니다(회전차량 우선)":"우선권은 진입차량이 아니라 회전차량에 있습니다.","집산도로, 간선도로, 국지도로가 도로 기능별 분류이고 지방도로는 아니다":"도로 기능별 분류는 집산도로, 간선도로, 국지도로이며 지방도로는 포함하지 않습니다.","짧은 변 90~150m 내외다":"국지도로끼리의 간격은 짧은 변 기준 90~150m 내외입니다.","차도 종단경사 5% 이하나 교차각 30도 이상은 기준이 아니다":"교차각 30도 이상이나 차도 종단경사 5% 이하는 기준에 들어가지 않습니다.","차두간격은 멀랑분포, 대향 간격은 음지수분포로 해석하며 RTOR 추정에 이항분포는 안 맞는다":"이항분포는 RTOR 추정에 맞지 않고, 차두간격은 멀랑분포, 대향 간격은 음지수분포로 해석합니다.","차두거리의 역수에 비례하며 교통량이 최대일 때 밀도를 임계밀도라 한다":"교통량이 최대일 때의 밀도를 임계밀도라 하며 밀도는 차두거리의 역수에 비례합니다.","차량가속도와 시간도 교통류 기본요소가 아니다":"교통류 기본요소에는 차량가속도와 시간도 들지 않습니다.","차량 규모·중량분포에 따라 마찰계수가 변하며 속도가 같아도 노면상태별 마찰계수는 다르다":"속도가 같아도 노면상태에 따라 마찰계수가 다르며 차량 규모와 중량분포에 따라서도 변합니다.","차량속도, 신호시간, 교차로간격은 시공도 작성 필수 요소이고 차량길이는 아니다":"차량길이는 시공도 작성의 필수 요소가 아니고 차량속도, 신호시간, 교차로간격이 필수 요소입니다.","차량의 관리, 교통의식의 개선은 포함되지 않는다":"차량의 관리와 교통의식의 개선은 포함 대상이 아닙니다.","차량의 중량은 속도 산출에 쓰이지 않는다":"속도를 산출할 때 차량의 중량은 쓰지 않습니다.","차량의 합류·분류·교차 위치와 각도를 조정하고 진행경로를 명확히 한다":"합류·분류·교차하는 차량의 위치와 각도를 조정하고 진행경로를 명확히 하는 것이 도류화입니다.","차량이 전도·급감속·튕겨나가지 않아야 하며 인접차로를 침범해도 되는 것은 아니다":"방호책에서는 차량이 전도되거나 급감속하거나 튕겨나가면 안 되고 인접차로를 침범해도 되는 것은 아닙니다.","차량·인체 최종 정지위치, 스키드마크, 노상 산란물을 현장에서 조사한다":"현장에서는 차량과 인체의 최종 정지위치, 스키드마크, 노상 산란물을 조사합니다.","차량 종류, 경사 길이, 경사도가 환산계수에 영향을 주며 차로폭은 아니다":"차로폭은 환산계수에 영향을 주지 않으며 차량 종류, 경사 길이, 경사도가 영향을 줍니다.","차량 종류·경사도·측방여유폭은 결정요소가 아니다":"결정요소에 차량 종류, 경사도, 측방여유폭은 들지 않습니다.","차로, 횡단보도, 길가장자리구역은 도로교통법상 정의된 용어다":"도로교통법상 정의된 용어에는 차로, 횡단보도, 길가장자리구역이 있습니다.","차로는 횡단보도·교차로·철길건널목에는 설치할 수 없다":"횡단보도와 교차로, 철길건널목에는 차로를 설치할 수 없습니다.","차로변경 필요길이, 회전차로 제약, 다음 교차로 인지성도 고려한다":"다음 교차로 인지성과 차로변경 필요길이, 회전차로 제약도 고려합니다.","차로수가 많다고 사고율이 낮은 것은 아니다":"사고율이 낮아지는 이유가 차로수 증가는 아닙니다.","차로 순위는 도로 오른쪽 가장자리부터 1차로이며 왼쪽부터가 아니다":"왼쪽이 아니라 도로 오른쪽 가장자리부터 1차로로 셉니다.","차로 최소폭은 3.5m이며 회전차로 2.5m는 해당 기준이 아니다":"회전차로 2.5m는 해당 기준이 아니며 지방지역 고속도로 차로 최소폭은 3.5m입니다.","차로폭 3.0m 이상, 승용차로만 구성된 교통류, 구배 0%가 이상적 조건이다":"구배 0%이고 승용차로만 교통류가 이뤄지며 차로폭이 3.0m 이상인 것이 이상적 조건입니다.","차로폭 3.5m 이상이나 측방여유폭 1.5m 이상은 이상적 조건이 아니다":"이상적 조건에 차로폭 3.5m 이상이나 측방여유폭 1.5m 이상은 들지 않습니다.","차로 폭은 교통량·대형차 혼입율, 서비스 수준, 설계속도를 고려하며 회전차로 수는 아니다":"회전차로 수가 아니라 교통량과 대형차 혼입율, 서비스 수준, 설계속도를 차로 폭 결정에 고려합니다.","차로폭은 설계속도 80km/h 이상·70km/h 이상 모두 3.25m다":"설계속도가 80km/h 이상이든 70km/h 이상이든 도시지역 일반도로 차로폭은 3.25m입니다.","차로폭이 넓으면 사고율이 낮고 노면표시로 사고가 줄며 억제형 중앙분리대가 효과적이다":"억제형 중앙분리대가 효과적이고 차로폭이 넓거나 노면표시가 있으면 사고율이 낮아집니다.","차선 공유가 가능하며 분리·동시신호는 교차로 특성에 따라 선택한다":"분리·동시신호는 교차로 특성에 따라 고르고, 동시신호는 차선 공유가 가능합니다.","차종, 차량번호, 통과시각이 차량번호판 조사 내용이다":"차량번호판 조사 내용은 차종, 차량번호, 통과시각입니다.","철도역 전면에는 역전광장을 설치하는 것이 바람직하다":"역전광장은 철도역 전면에 두는 것이 바람직합니다.","철도 확장·보수·제설을 위한 공간을 확보한다":"철도 횡단 교량은 철도 확장·보수·제설을 위한 공간을 확보합니다.","첨두시간 내 교통량 변동 정도를 나타낸다":"첨두시간 안에서 교통량이 얼마나 변하는지를 나타내는 값입니다.","총비용은 고정비와 변동비의 합이다":"고정비와 변동비를 합한 것이 총비용입니다.","최고제한속도, 정지횟수는 효과척도가 아니다":"최고제한속도와 정지횟수는 효과척도로 삼지 않습니다.","최대한도는 국토계획법 기준에 따르며 쾌적성 확보를 위한 공지 조성이 목적이다":"쾌적성 확보를 위한 공지 조성이 목적이며 최대한도는 국토계획법 기준에 따릅니다.","최소 1.0m로 고정된 것이 아니다":"보도의 유효폭은 최소 1.0m로 고정된 것이 아닙니다.","최소길이가 최소완화곡선 길이와 같은 것은 아니다":"최소길이가 곧 최소완화곡선 길이라고 할 수는 없습니다.","최소자승법, 등비급수법은 S자형 예측방법이 아니다":"S자형 예측방법에는 최소자승법과 등비급수법이 속하지 않습니다.","최저속도 30km/h, 최고속도 90km/h다":"자동차전용도로의 최저속도는 30km/h, 최고속도는 90km/h입니다.","최종 생산물의 외생적 영향력 예측에 쓰이며 중간재 투입정도를 판단할 수 있다":"최종 생산물의 외생적 영향력을 예측하고 중간재 투입정도를 판단하는 데 씁니다.","쵸커·시케인·라운드어바웃은 속도억제 기법이고 트랜짓몰은 아니다":"트랜짓몰은 속도억제 기법이 아니며 쵸커, 시케인, 라운드어바웃이 속도억제 기법입니다.","추월시거, 정지시거, 판단시거가 시거의 종류다":"시거의 종류에는 추월시거, 정지시거, 판단시거가 있습니다.","추월시거가 정지시거보다 대체로 더 길다":"추월시거는 대체로 정지시거보다 더 깁니다.","추월차량 운전자는 추월 개시 전 판단·반응시간이 필요하며 추월 중 가속한다":"추월 개시 전에 판단·반응시간이 필요하고 추월하는 동안 가속합니다.","추월차량은 기회를 찾으며 피추월차량과 같은 속도로 안전거리를 유지하며 따라간다":"피추월차량과 같은 속도로 안전거리를 유지하며 따라가다가 추월 기회를 찾는 것이 추월차량입니다.","출발시간, 통행목적, 환승여부가 가구통행조사 항목이고 통행경로는 아니다":"통행경로는 가구통행조사 항목이 아니며 출발시간, 통행목적, 환승여부가 항목입니다.","출발지·도착지 한 쌍을 하나 이상의 수단으로 이동하는 것이다":"한 쌍의 출발지·도착지를 하나 이상의 수단으로 이동하는 것이 목적통행입니다.","출입교통량 30,000대/일 이하, 세력권 인구 5~10만명 도시 부근에 배치한다":"세력권 인구 5~10만명 도시 부근, 출입교통량 30,000대/일 이하인 곳에 배치합니다.","출입제한은 가장 강한 접근관리기법이다":"접근관리기법 가운데 가장 강한 것이 출입제한입니다.","충격파는 상류·하류로 이동하거나 정지할 수 있고 유체역학적 개념이다":"상류나 하류로 이동하거나 정지할 수 있는 충격파는 유체역학적 개념입니다.","충돌도 준비, 사고특성 요약, 현장조사 실시가 위험지점 분석 4단계에 포함된다":"위험지점 분석 4단계에는 충돌도 준비, 사고특성 요약, 현장조사 실시가 속합니다.","충돌력의 방향·위치, 차량 회전방향을 나타내며 최초접촉지점은 아니다":"최초접촉지점이 아니라 충돌력의 방향·위치와 차량 회전방향을 나타내는 것이 충돌력 상황도입니다.","측방여유폭 1.5m 이상이 조건이며 추월금지구간 5% 이내는 조건이 아니다":"추월금지구간 5% 이내는 조건에서 빠지고, 측방여유폭 1.5m 이상이 갖춰야 할 조건입니다.","측방장애물까지 거리 1m 이상은 고속도로 기본구간 이상조건이 아니다":"고속도로 기본구간의 이상조건에 측방장애물까지 거리 1m 이상은 들지 않습니다.","치사율은 (사망자수/사고건수)×100(%)이며 부상자수로 나누지 않는다":"치사율은 사망자수를 사고건수로 나눈 값에 100을 곱해 구하며 부상자수로 나누지 않습니다.","친숙함 강화, 상징적 신호, 올바른 정보 제공이 반응시간을 줄이며 대안 수 최대화는 아니다":"대안 수 최대화는 반응시간을 줄이는 방법이 아니며 친숙함 강화, 상징적 신호, 올바른 정보 제공이 줄입니다.","카테고리분석법·원단위분석법·회귀분석법은 통행발생 모형이고 디트로이트법은 아니다":"통행발생 모형에는 카테고리분석법, 원단위분석법, 회귀분석법이 들고 디트로이트법은 아닙니다.","쿨데삭은 간선·보조간선 가로망 형태가 아니라 국지도로 형태다":"국지도로 형태이며 간선·보조간선 가로망 형태가 아닌 것이 쿨데삭입니다.","클로소이드·렘니스케이트 곡선, 3차 포물선은 완화곡선이고 2차 포물선은 아니다":"2차 포물선은 완화곡선이 아니며 클로소이드, 렘니스케이트 곡선, 3차 포물선이 완화곡선입니다.","타당성평가와 예비타당성조사 결과 간 현저한 차이가 있으면 추가 절차가 필요하다":"타당성평가와 예비타당성조사 결과 사이에 현저한 차이가 있으면 추가 절차를 거쳐야 합니다.","택지개발사업, 도시개발사업, 기업도시개발사업은 100만㎡ 이상이 기준이다":"100만㎡ 이상이 택지개발사업, 도시개발사업, 기업도시개발사업의 기준입니다.","터널·도로용 엘리베이터·도선장은 도로이고 가로수는 아니다":"터널, 도로용 엘리베이터, 도선장은 도로에 포함되고 가로수는 포함되지 않습니다.","터미널조사, 폐쇄선조사, 가구방문조사가 O-D 조사방법이다":"O-D 조사방법에는 터미널조사, 폐쇄선조사, 가구방문조사가 있습니다.","토지 공개념, 경제적 가족성, 개발이익 사회환원이 전원도시 요건이다":"전원도시의 요건에는 토지 공개념, 경제적 가족성, 개발이익 사회환원이 있습니다.","토지등기부등본, 공사설계도서, 토지이용상황 판단 축척도면을 첨부한다":"토지이용상황 판단 축척도면, 공사설계도서, 토지등기부등본이 첨부서류입니다.","토지생산성·산업별 생산액은 정성적 변수가 아니다":"산업별 생산액과 토지생산성은 정성적 변수에 들지 않습니다.","토지와 시설에 대한 물리적 계획의 3대 요소도 밀도·배치·동선이다":"밀도, 배치, 동선은 토지와 시설에 대한 물리적 계획의 3대 요소이기도 합니다.","토지이용·건축에 유리한 것은 방사환상형의 장점이 아니다":"방사환상형의 장점에 토지이용·건축에 유리한 점은 들어가지 않습니다.","토지이용과 교통은 상호의존적이며 순환적 관계를 가진다":"순환적 관계를 가지는 토지이용과 교통은 상호의존적입니다.","토지이용체계 변화가 정태적이라 교통 영향을 분리 관찰하기 쉬운 것은 아니다":"토지이용체계 변화가 정태적이므로 교통 영향을 분리해서 보기 쉽다고 할 수는 없습니다.","토지이용 합리화, 도시기능 증진·미관 개선, 양호한 환경 확보가 지구단위계획의 목적이다":"양호한 환경 확보와 토지이용 합리화, 도시기능 증진·미관 개선이 지구단위계획의 목적입니다.","통과교통 억제대책이지 환경개선대책은 아니다":"도로차단은 통과교통을 억제하는 대책이지 환경개선대책은 아닙니다.","통과교통이 생기기 쉽고 시각적으로 단조로우며 차도·보도가 교차한다":"통과교통이 생기기 쉽고 시각적으로 단조로우며 차도와 보도가 교차하는 것이 이 가로망의 특징입니다.","통과도로를 최대화하는 것은 주거단지 도로계획 고려사항이 아니다":"주거단지 도로계획에서 통과도로를 최대화하는 일은 고려사항이 아닙니다.","통과할 수 없으며 중앙분리선에 쓰이고 너비는 15~20cm다":"너비 15~20cm의 황색 실선은 중앙분리선에 쓰이며 통과할 수 없습니다.","통로(path), 경계(edge), 상징물(landmark)이 도시경관 형성요소다":"도시경관 형성요소에는 통로(path), 경계(edge), 상징물(landmark)이 있습니다.","통상 연 단위로 관리되며 핀·색종이로 지점을 표시한다":"사고 지점 표시는 통상 연 단위로 관리하며 핀이나 색종이로 지점을 표시합니다.","통행거리 증대, 교통표지판 설치 증가, 우회경로 확보 필요가 단점이다":"일방통행의 단점은 통행거리 증대, 교통표지판 설치 증가, 우회경로 확보 필요입니다.","통행 관련 자료, 토지이용 관련 자료, 교통체계 관련 자료가 기초자료 3종이다":"기초자료 3종은 통행, 토지이용, 교통체계와 관련된 자료입니다.","통행단모형, 로짓모형, 통행교차모형이 수단선택 예측모형이고 간섭기회모형은 아니다":"간섭기회모형은 수단선택 예측모형이 아니며 통행단모형, 로짓모형, 통행교차모형이 예측모형입니다.","통행료는 이익 받는 도로·관광도로·도서연결도로에서 받을 수 있다":"이익 받는 도로, 관광도로, 도서연결도로에서 통행료를 받을 수 있습니다.","통행료 지불 도로를 뜻하는 것은 아니다":"통행료 지불 도로를 가리키는 말이 아닙니다.","통행목적은 조사 내용이 아니다":"통행목적은 차량번호판 조사 내용이 아닙니다.","통행발생-수단분담-통행배분-노선배정 순으로 적용한다":"통행단모형은 통행발생, 수단분담, 통행배분, 노선배정 순으로 적용합니다.","통행발생 다음에 바로 노선배정이 오는 순서는 아니다":"통행발생 바로 다음 단계가 노선배정인 순서는 틀린 순서입니다.","통행 발생·도착량을 정확히 예측하는 것은 ITS의 목적이 아니다":"통행 발생·도착량의 정확한 예측은 ITS가 목적으로 삼는 일이 아닙니다.","통행배정은 교통문제 진단, 교통망 대안 평가, 시설 건설 우선순위 판단에 쓰인다":"교통문제 진단과 교통망 대안 평가, 시설 건설 우선순위 판단에 통행배정이 쓰입니다.","통행비용 절감, 통행시간 절약, 주변지역개발 효과가 경제성 평가의 편익이다":"경제성 평가의 편익은 통행비용 절감, 통행시간 절약, 주변지역개발 효과입니다.","통행시간을 최소화하는 경로를 선택하며 완전한 정보를 가정한다":"통행자는 통행시간을 최소화하는 경로를 고르며 완전한 정보를 가졌다고 가정합니다.","통행유입량을 목적지의 잠재적 기회 크기로 간주한다":"목적지의 잠재적 기회 크기로 통행유입량을 봅니다.","통행자가 전체 통행자의 총비용을 최소화하는 목적지를 고르는 것은 아니다":"총비용을 최소화하는 목적지를 전체 통행자가 함께 고른다는 설명은 틀립니다.","투입계수가 세분화·기술변화에 민감해도 안정적인 것은 아니다":"세분화나 기술변화에 투입계수가 민감하다고 해서 안정적인 것은 아닙니다.","트럼펫형·클로버형은 완전 입체교차다":"완전 입체교차에는 트럼펫형과 클로버형이 속합니다.","특별시도·지방도·시도는 도로법상 도로이고 유료도로는 아니다":"도로법상 도로에는 특별시도, 지방도, 시도가 속하고 유료도로는 속하지 않습니다.","특별시장·광역시장·시장·군수·구청장이 설치하며 요금은 조례로 정한다":"특별시장, 광역시장, 시장, 군수, 구청장이 노상주차장을 설치하며 요금은 조례로 정합니다.","특별시장·광역시장·시장·군수는 공청회로 주민·전문가 의견을 듣는다":"주민과 전문가의 의견은 특별시장, 광역시장, 시장, 군수가 공청회로 듣습니다.","특별시장·광역시장·시장이 신호기·안전표지를 설치하며 도지사는 아니다":"도지사가 아니라 특별시장, 광역시장, 시장이 신호기·안전표지를 설치합니다.","파랑 침식·세굴 방지용이 아니라 바람을 막는 시설이다":"바람을 막는 시설이 방풍시설이며 파랑 침식·세굴 방지용은 아닙니다.","편경사 6%에서 설계속도 100km/h의 최소 평면곡선반지름은 460m다":"설계속도 100km/h이고 편경사가 6%인 도로에서는 최소 평면곡선반지름이 460m로 정해집니다.","편경사가 곡선반경이 클수록 커지는 것은 아니다":"곡선반경이 클수록 편경사가 커지는 것은 아닙니다.","편도 2차로 도로는 앞지르기 금지장소가 아니다":"앞지르기 금지장소에 편도 2차로 도로는 들지 않습니다.","편도 2차로 이상 총길이 10km 이상 도로 신설·확장은 대상이 아니다":"도로 신설·확장이 편도 2차로 이상, 총길이 10km 이상이어도 대상은 아닙니다.","편익 항목에 포함되지 않는다":"통행료 수입은 편익 항목에 포함되지 않습니다.","평균대기시간과 평균서비스시간의 합이며 평균차량대수는 서비스 중 차량수와 다르다":"평균체류시간은 평균대기시간에 평균서비스시간을 더한 값으로 평균차량대수와 다른 개념입니다.","평균보행자지체·보행점유공간이 효과척도다":"신호횡단보도는 평균보행자지체와 보행점유공간이 효과척도입니다.","평균차량대수에서 서비스 중인 차량수를 뺀 값이다":"평균대기행렬 길이는 평균차량대수에서 서비스 중인 차량수를 뺀 값입니다.","평균통행거리, 다른 도로와의 연계체계, 교통관제시설 형태로 기능을 구분한다":"도로의 기능은 교통관제시설 형태와 평균통행거리, 다른 도로와의 연계체계를 보고 나눕니다.","평균 통행속도가 다차로도로 서비스수준 평가 효과척도다":"다차로도로 서비스수준 평가의 효과척도는 평균 통행속도입니다.","평면교차 동선을 2개소 이상 포함한다":"불완전 입체교차형은 평면교차 동선을 2개소 이상 포함합니다.","평면교차를 포함하지 않고 연결로가 독립돼 있다":"완전 입체교차형은 평면교차를 포함하지 않고 연결로가 독립돼 있습니다.","평면선형과 종단선형을 가급적 별개로 설계하는 것은 아니다":"평면선형과 종단선형은 각각 따로 설계하지 않고 서로 맞춰 설계하는 것이 바람직합니다.","평지 소형버스는 환산계수 1.0, 산지 2.5톤 미만 트럭은 1.5다":"환산계수는 평지 소형버스가 1.0이고 산지 2.5톤 미만 트럭이 1.5입니다.","평행식보다 주차대수가 많고 사고 가능성이 높다":"각도주차는 평행식보다 주차대수가 많은 대신 사고 가능성이 높습니다.","폐쇄선을 횡단하는 도로는 적게 하고 행정구역 경계와 일치시킨다":"폐쇄선을 가로지르는 도로는 줄이고 행정구역 경계와 일치시킵니다.","폐쇄선조사, 스크린라인조사, 가구방문조사가 사람통행실태조사 방법이다":"사람통행실태조사 방법에는 폐쇄선조사, 스크린라인조사, 가구방문조사가 있습니다.","폐쇄적 계획 추진에서 생기는 오류와 저항을 예방하고 주민 욕구를 목표에 반영한다":"주민 욕구를 목표에 반영하고 폐쇄적 계획 추진의 오류와 저항을 예방합니다.","포럼이 종교적 중심지인 것은 로마 도시의 특징이지 그리스는 아니다":"로마 도시는 포럼이 종교적 중심지였으나 그리스는 그렇지 않았습니다.","포아송·음이항·기하분포는 교통류 분포이고 정규분포는 아니다":"정규분포는 교통류 분포가 아니며 포아송, 음이항, 기하분포가 교통류 분포입니다.","포아송·이항·음이항분포는 계수분포이고 Erlang분포는 간격분포다":"Erlang분포는 간격분포이고 포아송, 이항, 음이항분포가 계수분포입니다.","포장이 안 돼 표시가 어려우면 표지판만으로 설치할 수 있다":"표시가 어려운 비포장 구간에는 표지판만으로 횡단보도를 설치할 수 있습니다.","포장재료·도색으로 도로 경관과 조화를 이룬다":"도로 경관과의 조화는 포장재료와 도색으로 이룹니다.","표본은 임의로 추출하며 대형차 혼입율을 고려한다":"대형차 혼입율을 고려하여 표본을 임의로 추출합니다.","표본크기 결정 고려사항이 아니다":"전수화방법은 표본크기를 정할 때의 고려사항이 아닙니다.","표준 10km, 최대 50km 간격으로 배치하는 것은 아니다(다른 간격 기준)":"휴게시설은 표준 10km, 최대 50km 간격으로 배치하는 것이 아닙니다.","표준구간, 전이구간, 끝부분이 노변방호책의 3가지 기능 구성요소다":"노변방호책의 3가지 기능 구성요소는 표준구간, 전이구간, 끝부분입니다.","프로빗모형, 로짓모형, 판별분석모형이 수단선택 과정에 쓰인다":"수단선택 과정에는 프로빗모형, 로짓모형, 판별분석모형이 쓰입니다.","피로·졸음은 안전운전 능력을 감소시키며 신체적 특성은 사고와 무관하지 않다":"신체적 특성은 사고와 무관하지 않으며 피로와 졸음은 안전운전 능력을 감소시킵니다.","피추월차량이 일정한 가속도로 주행한다고 가정하는 것은 아니다":"일정한 가속도로 피추월차량이 주행한다는 가정은 하지 않습니다.","피크시 도착통행량, 주차장 용적률·이용효율에 따라 수요가 변하며 특정 장소 예측에 적합하다":"특정 장소의 주차수요 예측에 적합한 이 방법은 피크시 도착통행량과 주차장 용적률, 이용효율에 따라 수요가 달라집니다.","필요성에 부응하고 간단명료하게 의미를 전달해야 한다":"간단명료하게 의미를 전달하고 필요성에 부응해야 합니다.","하나의 독립변수만 쓰는 것은 아니다":"다중선형회귀분석은 하나의 독립변수만 쓰는 것이 아닙니다.","하역주차구간, 외교공관 자동차, 조례가 정하는 자동차는 전용주차구획 설치가 가능하다":"전용주차구획은 하역주차구간, 외교공관 자동차, 조례가 정하는 자동차를 위해 설치할 수 있습니다.","하역주차구획 화물차 주차는 제한 대상이 아니다":"화물차가 하역주차구획에 주차하는 것은 제한하지 않습니다.","하워드의 전원도시 개념은 후에 신도시 개념의 모델이 되었다":"후에 신도시 개념의 모델이 된 것이 하워드의 전원도시 개념입니다.","하워드의 전원도시 계획안은 방사환상형 시가지 패턴을 가진다":"방사환상형 시가지 패턴을 가진 계획안이 하워드의 전원도시 계획안입니다.","학교·공용시설·항만시설 보호지구는 시설보호지구이고 특정시설보호지구는 아니다":"특정시설보호지구는 아니고 학교, 공용시설, 항만시설 보호지구가 시설보호지구입니다.","학교 등 서비스 공공시설은 주구 변두리가 아니라 중심에 위치한다":"주구 변두리가 아닌 중심에 학교 같은 서비스 공공시설을 둡니다.","학교·상가 등 생활편익시설과 연계되도록 계획한다":"주구는 학교와 상가 같은 생활편익시설과 연계되도록 계획합니다.","학교 앞, 어린이보호구역 등 저속 규제가 필요한 구간에 설치한다":"저속 규제가 필요한 학교 앞과 어린이보호구역 등에 설치합니다.","학교앞 300m 내 신호등이 없고 통학시간 차량간격이 짧으면 신호등을 설치한다":"통학시간 차량간격이 짧고 학교앞 300m 내에 신호등이 없으면 신호등을 설치합니다.","학교·유치원 인근 횡단보도에 신호등을 우선 설치한다":"신호등은 학교·유치원 인근 횡단보도에 우선 설치합니다.","합류상충, 교차상충, 분류상충이 평면교차로 상충 유형이다":"평면교차로 상충 유형은 합류상충, 교차상충, 분류상충입니다.","합리적 속도의 최대값을 나타내며 교통운영계획 기준속도로 삼는다":"교통운영계획의 기준속도로 삼는 속도가 합리적 속도의 최대값을 나타냅니다.","항공·항만·삭도교통안전관리자는 종류이고 궤도교통안전관리자는 아니다":"궤도교통안전관리자는 종류가 아니며 항공, 항만, 삭도 교통안전관리자가 종류입니다.","행정구역과 일치시키고 횡단 도로를 최소화하며 위성도시는 포함하지 않는다":"위성도시는 포함하지 않고 행정구역과 일치시키며 횡단 도로를 최소화하는 것이 폐쇄선 설정입니다.","현장 도로상 조사항목이 아니다":"직접 접촉 파손은 현장 도로상 조사항목이 아닙니다.","현재 교통체계 메커니즘이 장래에 크게 변하지 않는다고 가정한다":"장래에도 현재의 교통체계 메커니즘이 크게 달라지지 않으리라고 보는 가정을 둡니다.","현존하지 않는 대안의 선호정보를 평가할 수 없다":"RP데이터로는 현존하지 않는 대안에 대한 선호정보를 평가할 수 없습니다.","형평하고 광범위한 서비스 분배를 위해 정부 개입이 필요하다":"정부 개입이 필요한 이유는 대중교통이 형평하고 광범위하게 서비스를 나누어야 하기 때문입니다.","호텔·숙박시설은 150㎡당 1대 기준이 아니다":"호텔과 숙박시설에는 150㎡당 1대 기준을 적용하지 않습니다.","혼잡시간대가 평일 하루 3회 이상 발생하면 특별관리구역 지정 기준이다":"평일 하루 3회 이상 혼잡시간대가 발생하면 특별관리구역 지정 기준에 해당합니다.","혼잡통행료 부과·징수는 지방도시교통정책심의위원회 심의를 거쳐야 한다":"지방도시교통정책심의위원회 심의를 거쳐서 혼잡통행료를 부과·징수합니다.","화물을 내리기 위해 5분 이상 정지한 것은 정차가 아니다":"화물을 내리려 5분 이상 정지했다면 정차에 해당하지 않습니다.","화물 적재높이는 지상 4m 이내다":"지상 4m 이내까지가 화물 적재높이의 한도입니다.","화물차 운행제한·노상주차장 확충은 통행여건 개선조치가 아니다":"노상주차장 확충과 화물차 운행제한은 통행여건 개선조치에 들지 않습니다.","화살표·기호로 사고 관련 사항을 나타내며 반드시 축척에 맞출 필요는 없다":"사고 관련 사항을 화살표와 기호로 나타내기 때문에 반드시 축척에 맞출 필요가 없습니다.","화재경보기는 3m 이내가 기준이며 8m·5m는 아니다":"8m나 5m가 아니라 3m 이내가 화재경보기 기준입니다.","확률이 21.5%나 50.0%가 되는 것은 아니다":"이 경우 확률이 21.5%나 50.0%로 나오지는 않습니다.","환경·교통·재해 영향평가를 받지 않은 경우는 심의 생략 대상이 아니다":"심의 생략 대상에서 환경·교통·재해 영향평가를 받지 않은 경우는 빠집니다.","환경부문은 분류 항목에 포함되지 않는다":"환경부문은 라우리모형 분류 항목에 포함되지 않습니다.","환경영향평가는 환경부, 교통영향평가는 건설교통부가 관계 중앙행정기관이다":"교통영향평가는 건설교통부, 환경영향평가는 환경부가 관계 중앙행정기관입니다.","황색바탕이 아니라 백색바탕에 적색이다":"진입금지표지는 백색바탕에 적색이고 황색바탕이 아닙니다.","황색시간은 보통 3~6초이며 교차로 횡단길이가 길수록 길어진다":"교차로 횡단길이가 길수록 황색시간이 길어지며 보통 3~6초입니다.","황색신호 시 교차로 부근 차량이 급정지하지 않고 진행하는 시간이다":"진행연장시간은 황색신호 때 교차로 부근 차량이 급정지하지 않고 진행하는 시간입니다.","황색은 반대방향 교통류 분리를 뜻한다":"황색 노면표시는 반대방향 교통류 분리를 뜻합니다.","회귀분석법·로짓모형·프로빗모형은 개별행태 분석 모형이고 디트로이트모형은 아니다":"디트로이트모형은 개별행태 분석 모형이 아니며 회귀분석법, 로짓모형, 프로빗모형이 분석 모형입니다.","회전교통량 처리와 진출입에 엄격히 관리하며 산지 종단경사 5% 초과가 연결금지구간 기준은 아니다":"간선도로는 진출입과 회전교통량 처리를 엄격히 관리하고, 산지 종단경사 5% 초과는 연결금지구간 기준이 아닙니다.","회전차로 폭은 최소 2.5m 이상이다":"최소 2.5m 이상의 폭이 회전차로에 필요합니다.","횡단보도는 육교·지하도·다른 횡단보도로부터 100m 이내에는 설치하지 않는다":"육교, 지하도, 다른 횡단보도에서 100m 이내인 곳에는 횡단보도를 설치하지 않습니다.","횡단보도와 정지선 간격을 좁히는 것은 방지대책이 아니다":"사고방지대책에서 횡단보도와 정지선 간격을 좁히는 일은 빠집니다.","횡단보도표시·표지판을 설치하며 포장이 안 돼 있으면 표시를 생략할 수 있다":"포장이 안 돼 있으면 횡단보도 표시를 생략할 수 있고 표지판도 설치합니다.","효과척도로 공간평균속도를 쓰는 것은 아니다":"공간평균속도를 효과척도로 쓰는 것은 아닙니다.","효용값 -0.18, -1.15일 때 선택확률은 PB=0.72, PS=0.28이다":"효용값이 -0.18과 -1.15일 때 버스와 지하철 선택확률은 각각 0.72, 0.28입니다.","효용값이 -5.545, -4.874일 때 선택확률은 P(A)=0.3383, P(B)=0.6617이다":"효용값이 -5.545와 -4.874일 때 승용차와 버스 선택확률은 각각 0.3383, 0.6617입니다.","후륜 흔적이 전륜 흔적을 벗어나지 않으면 직선미끄럼으로 간주한다":"직선미끄럼은 후륜 흔적이 전륜 흔적을 벗어나지 않는 경우로 간주합니다.","후륜 흔적이 전륜 흔적 한쪽을 벗어나면 곡선미끄럼이며 평균거리로 하지 않는다":"곡선미끄럼은 후륜 흔적이 전륜 흔적 한쪽을 벗어나는 경우이며 거리는 평균으로 구하지 않습니다.","희생자수 대신 사고건수를 나타내는 것이 일반적이다":"희생자수 대신 사고건수를 표시하는 것이 일반적입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
